    if typ==257:
        f,tag,v=spec.split(' ',2)
        return bytes([int(f),len(tag)])+tag.encode()+v.encode()
    if typ==44:
        a,ft,fp=spec.split(' ',2); return bytes([int(a),int(ft)])+bytes.fromhex(fp)
    if typ==52:
        u,s,m,d=spec.split(' ',3); return bytes([int(u),int(s),int(m)])+bytes.fromhex(d)
    if typ==29:
        parts=spec.split(' ')
        return struct.pack('!HHH',int(parts[0]),int(parts[1]),int(parts[2]))+enc_name(parts[3])
    if typ==35:  # NSEC
        return enc_name(spec)
    if typ==27:
        return bytes.fromhex(spec)
    if typ==43:  # DS
        return bytes.fromhex(spec)
    if typ==249:
        return spec.encode()
    if typ==3:
        return struct.pack('!H',int(spec))
