    flags|=(AA and 0x0400)
    flags|=(AD and 0x0020)
    flags|=(CD and 0x0010)
    flags|=(RCODE&0xF)
    def sect(specs):
        out=b''
        for (t,v,c,tl) in specs:
            d=rdata(qname,t,v)
            out+=enc_name(qname)+struct.pack('!HHIH',t,c if c is not None else qclass,tl if tl is not None else TTL,len(d))+d
        return out
    an=sect(ANSWERS); au=sect(AUTHORITIES); ad=sect(ADDITIONALS)
    extra=b''
    if OPT=='1':
        rd=struct.pack('!H',1232)
        extra=b'\x00'+struct.pack('!HHIH',41,1,0,len(rd))+rd
    hdr=struct.pack('!HHHHHH',tid,flags,1,len(ANSWERS),len(AUTHORITIES),len(ADDITIONALS)+(1 if extra else 0))
    return hdr+enc_name(qname)+struct.pack('!HH',qtype,qclass)+an+au+ad+extra

def qname_data(raw):
    out=[];i=0
    while i<len(raw):
        l=raw[i]
        if l==0:break
        out.append(raw[i+1:i+1+l].decode());i+=1+l
    return '.'.join(out)+'.'

def parse_q(data):
    tid,flags,qd,an,ns,ar=struct.unpack('!HHHHHH',data[:12])
    i=12
    while data[i]!=0: i+=1+data[i]
    i+=1
    qtype,qclass=struct.unpack('!HH',data[i:i+4]);i+=4
    return tid,flags,qname_data(data[12:i-5]),qtype,qclass,i

def handle_udp(sock):
    data,addr=sock.recvfrom(4096)
    print('UDPQ',data.hex(),file=sys.stderr)
    try:
        tid,flags,qn,qt,qc,off=parse_q(data)
        if QNAMEFORCE: qn=QNAMEFORCE
        resp=build_response(qn,qt,qc,tid)
        sock.sendto(resp,addr)
    except Exception as e:
        print('udp err',e,file=sys.stderr)

def handle_tcp(conn):
    conn.settimeout(5)
    try:
        hdr=conn.recv(2)
        if len(hdr)<2: return
        l=struct.unpack('!H',hdr)[0]
        data=b''
        while len(data)<l:
            c=conn.recv(l-len(data))
            if not c:break
            data+=c
        print('TCPQ',data.hex(),file=sys.stderr)
        tid,flags,qn,qt,qc,off=parse_q(data)
        if QNAMEFORCE: qn=QNAMEFORCE
        resp=build_response(qn,qt,qc,tid)
        if TC:
            resp=resp[:12+len(enc_name(qn))+4]
        conn.sendall(struct.pack('!H',len(resp))+resp)
    except Exception as e:
        print('tcp err',e,file=sys.stderr)

u=socket.socket(socket.AF_INET,socket.SOCK_DGRAM)
u.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)
u.bind(('127.0.0.1',PORT))
t=socket.socket(socket.AF_INET,socket.SOCK_STREAM)
t.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)
t.bind(('127.0.0.1',PORT))
t.listen(5)
def uloop():
    while True:
        try: handle_udp(u)
        except Exception as e: print('udp err',e,file=sys.stderr)
def tloop():
    while True:
        c,_=t.accept()
        threading.Thread(target=handle_tcp,args=(c,),daemon=True).start()
threading.Thread(target=uloop,daemon=True).start()
tloop()
