import socket,ssl,os,struct,sys,threading,time
PORT=int(os.environ.get('PORT','443'))
MODE=os.environ.get('MODE','http11')
STATUS=os.environ.get('STATUS','200')
def enc(n):
    out=b''
    for p in n.rstrip('.').split('.'):
        if p: out+=bytes([len(p)])+p.encode()
    return out+b'\x00'
def build_dns(buf):
    idx=buf.find(bytes([0x01,0x00,0x00,0x01]))
    if idx<0: return None
    start=idx-2
    tid,flags,qd,an,ns,ar=struct.unpack('!HHHHHH',buf[start:start+12])
    i=start+12
    while buf[i]!=0: i+=1+buf[i]
    i+=5
    anr=enc('doh.example.net.')+struct.pack('!HHIH',1,1,300,4)+bytes([9,9,9,9])
    return struct.pack('!HHHHHH',tid,flags,1,1,0,0)+buf[start+12:i]+anr
