        while True:
            d=tls.recv(65535)
            if not d: break
            buf+=d
            print('TLS recv %d bytes: %s'%(len(d),d.hex()),file=sys.stderr)
    except Exception as e:
        print('recv err',repr(e),file=sys.stderr)
    body=build_dns(buf)
    print('body len',len(body) if body else None,file=sys.stderr)
    if body:
        if MODE=='http11':
            resp=b'HTTP/1.1 '+STATUS.encode()+b' OK\r\nContent-Type: application/dns-message\r\nContent-Length: '+str(len(body)).encode()+b'\r\n\r\n'+body
        elif MODE=='nopre':
            resp=b'HTTP/1.1 '+STATUS.encode()+b' OK\r\nContent-Type: application/dns-message\r\n\r\n'+body
        elif MODE=='truncated':
            resp=b'HTTP/1.1 '+STATUS.encode()+b' OK\r\nContent-Length: '+str(len(body)+10).encode()+b'\r\n\r\n'+body
        else:
            resp=b'HTTP/1.1 '+STATUS.encode()+b' OK\r\nContent-Length: '+str(len(body)).encode()+b'\r\n\r\n'+body
        tls.sendall(resp)
        print('sent response',file=sys.stderr)
