cd /workspace && u(){ printf "%-22s " "$1"; timeout 6 ./executable -T -n "$1" example.net >/tmp/t/o 2>/tmp/t/e; echo "rc=$? out=[$(cat /tmp/t/o)] err=[$(head -c 100 /tmp/t/e|tr '\n' '|')]"; }
for ns in "1.2.3.4:abc" "://127.0.0.1" "[::1]:5353" "1.2.3.4:53:53" "localhost:5353"; do u "$ns"; done
