use std::net::*;
fn main(){
  for s in ["1.2.3.4:abc","1.2.3.4:","1.2.3.4:0","1.2.3.4:70000","1.2.3.4:53:53","://127.0.0.1","[::1]:5353","::1:5353","localhost:5353","127.0.0.1:5353","","127.0.0.1","localhost"] {
    match s.to_socket_addrs() {
      Ok(mut it) => { let v: Vec<SocketAddr> = it.by_ref().collect(); println!("{:>20} => OK {:?}", s, v); }
      Err(e) => println!("{:>20} => ERR {}", s, e),
    }
    match (s.rsplit_once(':').map(|(h,p)| (h, p.parse::<u16>()).to_socket_addrs()), None::<()>) {
      _ => {}
    }
  }
}
EOF
cd /tmp/rtest && rustc -O main.rs -o rt 2>&1 | head -3; ./rt

