//! DNS protocol types shared by dog.

pub mod name;
pub mod punycode;
pub mod records;
pub mod wire;

/// A duration that can be formatted in dog's human readable style.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Duration {
    pub secs: u64,
    pub millis: u32,
}

impl Duration {
    pub fn from_secs(secs: u64) -> Self {
        Duration { secs, millis: 0 }
    }

    pub fn total_secs(&self) -> u64 {
        self.secs
    }

    pub fn total_millis(&self) -> u64 {
        self.secs * 1000 + self.millis as u64
    }

    /// Format in dog's `5m00s` style.
    pub fn human(&self) -> String {
        let mut secs = self.secs;
        if secs < 60 {
            return format!("{}s", secs);
        }
        let minutes = secs / 60;
        secs %= 60;
        if minutes < 60 {
            return format!("{}m{:02}s", minutes, secs);
        }
        let hours = minutes / 60;
        let minutes = minutes % 60;
        if hours < 24 {
            return format!("{}h{:02}m{:02}s", hours, minutes, secs);
        }
        let days = hours / 24;
        let hours = hours % 24;
        format!("{}d{:02}h{:02}m{:02}s", days, hours, minutes, secs)
    }
}

/// DNS record classes dog knows about.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Class {
    Internet,
    Hesiod,
    Chaos,
    Other(u16),
}

impl Class {
    pub fn name(&self) -> String {
        match self {
            Class::Internet => "IN".to_string(),
            Class::Hesiod => "HS".to_string(),
            Class::Chaos => "CH".to_string(),
            Class::Other(n) => n.to_string(),
        }
    }

    pub fn number(&self) -> u16 {
        match self {
            Class::Internet => 1,
            Class::Chaos => 3,
            Class::Hesiod => 4,
            Class::Other(n) => *n,
        }
    }

    pub fn debug(&self) -> String {
        match self {
            Class::Internet => "IN".to_string(),
            Class::Chaos => "CH".to_string(),
            Class::Hesiod => "HS".to_string(),
            Class::Other(n) => format!("Other({})", n),
        }
    }

    pub fn from_number(num: u16) -> Self {
        match num {
            1 => Class::Internet,
            3 => Class::Chaos,
            4 => Class::Hesiod,
            n => Class::Other(n),
        }
    }

