import unicodedata as ud
MAX=0x2FFF
# casefold: cp -> fold string (differs from simple lowercase)
fold={}
for cp in range(0x80, MAX+1):
    c=chr(cp)
    f=c.lower()
    if f!=c and len(f)<=2:
