{"command": "cat > dns/src/punycode.rs <<'EOF'
//! RFC 3492 punycode encoding and decoding.

const BASE: u32 = 36;
const TMIN: u32 = 1;
const TMAX: u32 = 26;
const SKEW: u32 = 38;
const DAMP: u32 = 700;
const INITIAL_BIAS: u32 = 72;
const INITIAL_N: u32 = 128;

fn digit_value(cp: u32) -> Option<u32> {
    match cp {
        0x41..=0x5A => Some(cp - 0x41),        // A-Z
        0x61..=0x7A => Some(cp - 0x61),        // a-z
        0x30..=0x39 => Some(cp - 0x30 + 26),   // 0-9
        _ => None,
    }
}

fn digit(d: u32) -> char {
    if d < 26 {
        (0x61 + d) as u8 as char
    } else {
        (0x30 + d - 26) as u8 as char
    }
}

fn adapt(mut delta: u32, num_points: u32, first_time: bool) -> u32 {
    delta = if first_time { delta / DAMP } else { delta / 2 };
    delta += delta / num_points;
    let mut k = 0;
    while delta > ((BASE - TMIN) * TMAX) / 2 {
        delta /= BASE - TMIN;
        k += BASE;
    }
    k + (((BASE - TMIN + 1) * delta) / (delta + SKEW))
}

/// Encode a sequence of characters using punycode. Returns the encoded ASCII string.
pub fn encode(input: &[char]) -> Option<String> {
    let mut output: Vec<char> = Vec::new();
    let mut non_basic: Vec<char> = Vec::new();
    for &c in input {
        if (c as u32) < INITIAL_N {
            output.push(c);
        } else {
            non_basic.push(c);
        }
    }
    let mut h = output.len() as u32;
    let basic_count = h;
    if basic_count > 0 {
        output.push('-');
    }
    if non_basic.is_empty() {
        if basic_count == input.len() as u32 {
            return Some(output.iter().collect());
        }
        return None;
    }
    let mut n = INITIAL_N;
    let mut delta: u32 = 0;
