//! Domain names: dog's representation, IDNA handling and validation.

use crate::punycode;
use crate::tables;

/// A domain name, stored as its separate labels.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Labels {
    pub segments: Vec<(usize, String)>,
}

impl Labels {
    pub fn new() -> Self {
        Labels { segments: Vec::new() }
    }

    pub fn len(&self) -> usize {
        self.segments.len()
    }

    pub fn is_empty(&self) -> bool {
        self.segments.is_empty()
    }

    /// The display form, with a trailing dot, ready to go on the wire.
    pub fn to_string(&self) -> String {
        let mut out = String::new();
        for (_, seg) in &self.segments {
            out.push_str(seg);
            out.push('.');
        }
        out
    }

    pub fn wire_len(&self) -> usize {
        let mut len = 1;
        for (n, seg) in &self.segments {
            len += 1 + n;
        }
        len
    }

    pub fn bytes(&self) -> Vec<u8> {
        let mut out = Vec::new();
        for (n, seg) in &self.segments {
            out.push(*n as u8);
            out.extend_from_slice(seg.as_bytes());
        }
        out.push(0);
        out
    }

    /// Parse an argument into a domain name, using dog's IDNA handling.
    pub fn parse(text: &str) -> Result<Self, ()> {
        let mut segments = Vec::new();
        for part in text.split('.') {
            if part.is_empty() {
                continue;
            }
            let label = label_to_ascii(part)?;
            if label.len() > 63 {
                return Err(());
            }
            if label.starts_with("xn--") {
                let raw = &label[4..];
                let decoded = match punycode::decode(raw) {
                    Some(chars) => chars,
                    None => return Err(()),
                };
                let re = match punycode::encode(&decoded) {
                    Some(s) => s,
                    None => return Err(()),
                };
                if re != raw {
                    return Err(());
                }
                if decoded.iter().any(|c| is_prohibited(*c)) {
                    return Err(());
                }
            }
            segments.push((label.len(), label));
        }
        Ok(Labels { segments })
    }

    /// Read a domain name off the wire, following compression pointers.
    pub fn read_wire(buf: &[u8], pos: &mut usize) -> Result<Self, WireError> {
        let mut segments: Vec<(usize, String)> = Vec::new();
        let mut recursion = 0usize;
        let mut jump: Option<usize> = None;
        let mut cur = *pos;
        loop {
            recursion += 1;
            if recursion > 32 {
                return Err(WireError::TooMuchRecursion(cur));
            }
            if cur >= buf.len() {
                return Err(WireError::InsufficientData);
            }
            let len = buf[cur] as usize;
            if len == 0 {
                cur += 1;
                if jump.is_none() {
                    *pos = cur;
                } else {
                    *pos = jump.unwrap() + 1;
                }
                break;
            }
            if len & 0xC0 == 0xC0 {
                if cur + 1 >= buf.len() {
                    return Err(WireError::InsufficientData);
                }
                let target = ((len as usize & 0x3F) << 8) | buf[cur + 1] as usize;
                if jump.is_none() {
                    jump = Some(cur);
                }
                if target >= buf.len() {
                    return Err(WireError::InsufficientData);
                }
                cur = target;
