        | 0x180E | 0x200B | 0x2060..=0x2064 | 0x206A..=0x206F | 0xFEFF | 0xFFF9..=0xFFFC)
}

/// RFC 3454 table B.2: characters mapped to a space.
fn mapped_to_space(c: char) -> bool {
    let cp = c as u32;
    matches!(cp,
        0x00A0 | 0x1680 | 0x2000..=0x2006 | 0x2008..=0x200A | 0x2028 | 0x2029 | 0x202F
        | 0x205F | 0x3000)
}

/// Characters that dog rejects outright.
pub fn is_prohibited(c: char) -> bool {
    let cp = c as u32;
    if cp > 0x2FFF {
        // Non-characters and the replacement character are always out.
        if cp == 0xFFFD || cp == 0xFFFE || cp == 0xFFFF {
            return true;
        }
        return matches!(cp, 0x1FFFE | 0x1FFFF);
    }
    if cp >= 0xFFFE && cp <= 0xFFFF {
        return true;
    }
    if unassigned(cp) {
        return true;
    }
    matches!(cp,
        0x000C | 0x000D | 0x0080..=0x009F | 0x200E | 0x200F | 0x202A..=0x202E
        | 0x2066..=0x2069 | 0x0640)
}

fn unassigned(cp: u32) -> bool {
    for &(a, b) in tables::UNASSIGNED {
        if cp >= a as u32 && cp <= b as u32 {
            return true;
        }
    }
    false
}

fn fold_char(c: char, out: &mut String) {
    let cp = c as u32;
    if cp <= 0x7F {
        out.push(c.to_ascii_lowercase());
        return;
    }
    if cp > 0x2FFF {
        out.push(c);
        return;
    }
    for &(a, b, d) in tables::FOLD_RANGES {
        if cp >= a as u32 && cp <= b as u32 {
            if let Some(nc) = char::from_u32((cp as i32 + d) as u32) {
                out.push(nc);
                return;
            }
        }
    }
    for &(a, s) in tables::FOLD_MULTI {
        if a as u32 == cp {
            out.push_str(s);
            return;
        }
    }
    out.push(c);
}

/// Apply RFC 3454 mapping and Unicode case folding to one character.
fn map_char(c: char, out: &mut String) {
    if mapped_to_nothing(c) {
        return;
    }
    if mapped_to_space(c) {
        out.push(' ');
        return;
    }
    fold_char(c, out);
}

fn compose(input: &str) -> String {
    let chars: Vec<char> = input.chars().collect();
    let mut out: Vec<char> = Vec::new();
    let mut last_class = 0i8;
    for &c in &chars {
        let class = combining_class(c);
        if class == 0 {
            // starter: try to compose with the last starter
            let mut composed = false;
            if let Some(&last) = out.last() {
                if last_class != 255 {
                    if let Some(combined) = find_composition(last, c) {
                        out.pop();
                        out.push(combined);
                        composed = true;
                    }
                }
            }
            if !composed {
                out.push(c);
            }
            last_class = class;
        } else {
            let mut composed = false;
            for i in (0..out.len()).rev() {
                let starter = out[i];
                let starter_class = if i == 0 { 0 } else { combining_class(out[i - 1]) };
                if starter_class == 0 {
                    if let Some(combined) = find_composition(starter, c) {
                        out[i] = combined;
                        composed = true;
                    }
                    break;
                }
            }
            if !composed {
                out.push(c);
            }
        }
    }
    out.iter().collect()
}

fn combining_class(c: char) -> i8 {
    let cp = c as u32;
    if cp >= 0x0300 && cp <= 0x036F {
        return 230;
    }
    match cp {
        0x0334..=0x0338 => 1,
        0x0340 | 0x0341 | 0x0343 | 0x0344 | 0x0346..=0x034E => 230,
        0x0345 => 240,
        0x0342 => 232,
        0x0358..=0x035E => 230,
        0x0362 => 230,
        _ => 0,
    }
}

fn find_composition(a: char, b: char) -> Option<char> {
    let (ap, bp) = (a as u32, b as u32);
    for &(x, y, z) in tables::COMPOSITIONS {
        if x as u32 == ap && y as u32 == bp {
            return char::from_u32(z as u32);
        }
    }
    None
}

fn nfkc_char(c: char, out: &mut String) {
    let cp = c as u32;
    if cp <= 0x7F {
        out.push(c);
        return;
    }
    if cp > 0x2FFF {
        out.push(c);
        return;
    }
    for &(a, b, d) in tables::NFKC_RANGES {
        if cp >= a as u32 && cp <= b as u32 {
            if let Some(nc) = char::from_u32((cp as i32 + d) as u32) {
                out.push(nc);
                return;
            }
        }
    }
    for &(a, s) in tables::NFKC_MULTI {
        if a as u32 == cp {
            out.push_str(s);
            return;
        }
    }
    out.push(c);
}

/// dog's IDNA "label to ASCII" step.
pub fn label_to_ascii(label: &str) -> Result<String, ()> {
    let mut mapped = String::new();
    for c in label.chars() {
        map_char(c, &mut mapped);
    }
    let mut nk = String::new();
    for c in mapped.chars() {
        nfkc_char(c, &mut nk);
    }
    let composed = compose(&nk);
    for c in composed.chars() {
        if is_prohibited(c) {
            return Err(());
        }
    }
    if composed.chars().all(|c| (c as u32) < 0x80) {
        return Ok(composed);
    }
    let chars: Vec<char> = composed.chars().collect();
    let encoded = punycode::encode(&chars).ok_or(())?;
    Ok(format!("xn--{}", encoded))
}
