//! Record types and the human-readable / JSON forms of their contents.

use crate::name::{Labels, WireError};
use crate::wire::Reader;

/// Record types that dog knows the number of.
#[derive(Clone, PartialEq, Eq, Hash, Debug)]
pub enum RecordType {
    A,
    AAAA,
    CNAME,
    NS,
    PTR,
    SOA,
    MX,
    TXT,
    HINFO,
    SRV,
    SSHFP,
    TLSA,
    CAA,
    LOC,
    OPT,
    Other(OtherType),
}

#[derive(Clone, PartialEq, Eq, Hash, Debug)]
pub enum OtherType {
    HeardOf(String, u16),
    UnheardOf(u16),
}

/// Types whose contents dog can interpret.
pub const KNOWN: &[(u16, &str)] = &[
    (1, "A"),
    (2, "NS"),
    (5, "CNAME"),
    (6, "SOA"),
    (12, "PTR"),
    (13, "HINFO"),
    (15, "MX"),
    (16, "TXT"),
    (28, "AAAA"),
    (29, "LOC"),
    (33, "SRV"),
    (41, "OPT"),
    (44, "SSHFP"),
    (52, "TLSA"),
    (257, "CAA"),
];

/// Types dog has heard of, but cannot interpret.
pub const HEARD_OF: &[(u16, &str)] = &[
    (17, "RP"),
    (18, "AFSDB"),
    (23, "SIG"),
    (25, "KEY"),
    (35, "NAPTR"),
    (36, "KX"),
    (37, "CERT"),
    (43, "DS"),
    (45, "IPSECKEY"),
    (46, "RRSIG"),
    (47, "NSEC"),
    (50, "NSEC3"),
    (51, "NSEC3PARAM"),
    (53, "SMIMEA"),
    (55, "HIP"),
    (61, "OPENPGPKEY"),
    (62, "CSYNC"),
    (249, "TKEY"),
    (251, "IXFR"),
    (252, "AXFR"),
    (254, "APL"),
    (255, "ANY"),
    (32769, "TA"),
    (32770, "DLV"),
];

impl RecordType {
    pub fn number(&self) -> u16 {
        match self {
            RecordType::A => 1,
            RecordType::AAAA => 28,
            RecordType::CNAME => 5,
            RecordType::NS => 2,
            RecordType::PTR => 12,
            RecordType::SOA => 6,
            RecordType::MX => 15,
            RecordType::TXT => 16,
            RecordType::HINFO => 13,
            RecordType::SRV => 33,
            RecordType::SSHFP => 44,
            RecordType::TLSA => 52,
            RecordType::CAA => 257,
            RecordType::LOC => 29,
            RecordType::OPT => 41,
            RecordType::Other(OtherType::UnheardOf(n)) => *n,
            RecordType::Other(OtherType::HeardOf(_, n)) => *n,
        }
    }

    pub fn name(&self) -> String {
        match self {
            RecordType::Other(OtherType::UnheardOf(n)) => n.to_string(),
            _ => self::name_of(self.number()).to_string(),
        }
    }

    pub fn debug(&self) -> String {
        match self {
            RecordType::Other(OtherType::HeardOf(name, num)) => format!(
                "Other(\n                    HeardOf(\n                        {:?},\n                        {},\n                    ),\n                )",
                name, num
            ),
            RecordType::Other(OtherType::UnheardOf(num)) => format!(
                "Other(\n                    UnheardOf(\n                        {},\n                    ),\n                )",
                num
            ),
            _ => self.name(),
        }
    }

    pub fn from_number(num: u16) -> Self {
        if let Some(&(_, name)) = KNOWN.iter().find(|(n, _)| *n == num) {
            return from_name(name);
        }
        if let Some(&(_, name)) = HEARD_OF.iter().find(|(n, _)| *n == num) {
            return RecordType::Other(OtherType::HeardOf(name.to_string(), num));
        }
        RecordType::Other(OtherType::UnheardOf(num))
    }

    pub fn parse(text: &str) -> Option<Self> {
        if text.eq_ignore_ascii_case("OPT") {
            return None;
        }
        if let Ok(num) = text.parse::<u16>() {
            return Some(RecordType::Other(OtherType::UnheardOf(num)));
        }
        for &(_, name) in KNOWN.iter().chain(HEARD_OF.iter()) {
            if text.eq_ignore_ascii_case(name) {
                return Some(from_name(name));
            }
        }
        None
    }
}

fn from_name(name: &str) -> RecordType {
    match name {
        "A" => RecordType::A,
        "AAAA" => RecordType::AAAA,
        "CNAME" => RecordType::CNAME,
        "NS" => RecordType::NS,
        "PTR" => RecordType::PTR,
        "SOA" => RecordType::SOA,
        "MX" => RecordType::MX,
        "TXT" => RecordType::TXT,
        "HINFO" => RecordType::HINFO,
        "SRV" => RecordType::SRV,
        "SSHFP" => RecordType::SSHFP,
        "TLSA" => RecordType::TLSA,
        "CAA" => RecordType::CAA,
        "LOC" => RecordType::LOC,
        "OPT" => RecordType::OPT,
        other => {
            let num = HEARD_OF
                .iter()
                .find(|(_, n)| *n == other)
                .map(|(n, _)| *n)
                .unwrap_or(0);
            RecordType::Other(OtherType::HeardOf(other.to_string(), num))
        }
    }
}

pub fn name_of(num: u16) -> &'static str {
    for &(n, name) in KNOWN.iter().chain(HEARD_OF.iter()) {
        if n == num {
            return name;
        }
    }
    ""
}

/// The contents of a DNS record, as dog interprets them.
#[derive(Clone, PartialEq, Eq, Debug)]
pub enum RecordData {
    A([u8; 4]),
    AAAA([u8; 16]),
    CNAME(String),
    NS(String),
    PTR(String),
    SOA {
        mname: String,
        rname: String,
        serial: u32,
        refresh: u32,
        retry: u32,
        expire: u32,
        minimum: u32,
    },
    MX { preference: u16, exchange: String },
    TXT(Vec<Vec<u8>>),
    HINFO { cpu: String, os: String },
    SRV { priority: u16, weight: u16, port: u16, target: String },
    SSHFP { algorithm: u8, fingerprint_type: u8, fingerprint: String },
    TLSA { usage: u8, selector: u8, matching: u8, data: String },
    CAA { critical: bool, tag: String, value: Vec<u8> },
    LOC {
        size: String,
        precision_horizontal: u8,
        precision_vertical: u8,
        latitude: Option<String>,
        longitude: Option<String>,
        altitude: String,
    },
    OPT { version: u8, data: Vec<u8> },
    Unknown(Vec<u8>),
}

fn escape_text(bytes: &[u8]) -> String {
    let mut out = String::new();
    for &b in bytes {
        if b == b'"' {
            out.push('\\');
            out.push('"');
        } else if b == b'\\' {
            out.push('\\');
            out.push('\\');
        } else if b < 0x20 || b > 0x7F {
            out.push('\\');
            out.push_str(&b.to_string());
        } else {
            out.push(b as char);
        }
    }
    out
}

fn json_string(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).to_string()
}

fn json_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{08}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{0c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

impl RecordData {
    pub fn type_name(&self) -> String {
        match self {
            RecordData::A(_) => "A".into(),
            RecordData::AAAA(_) => "AAAA".into(),
            RecordData::CNAME(_) => "CNAME".into(),
            RecordData::NS(_) => "NS".into(),
            RecordData::PTR(_) => "PTR".into(),
            RecordData::SOA { .. } => "SOA".into(),
            RecordData::MX { .. } => "MX".into(),
            RecordData::TXT(_) => "TXT".into(),
            RecordData::HINFO { .. } => "HINFO".into(),
            RecordData::SRV { .. } => "SRV".into(),
            RecordData::SSHFP { .. } => "SSHFP".into(),
            RecordData::TLSA { .. } => "TLSA".into(),
            RecordData::CAA { .. } => "CAA".into(),
            RecordData::LOC { .. } => "LOC".into(),
            RecordData::OPT { .. } => "OPT".into(),
            RecordData::Unknown(_) => "".into(),
        }
    }

    /// The colour code dog paints the record type with.
    pub fn colour(&self) -> &'static str {
        match self {
            RecordData::A(_) | RecordData::AAAA(_) => "1;32",
            RecordData::NS(_) | RecordData::PTR(_) | RecordData::CAA { .. } => "31",
            RecordData::CNAME(_)
            | RecordData::TXT(_)
            | RecordData::HINFO { .. }
            | RecordData::TLSA { .. }
            | RecordData::LOC { .. } => "33",
            RecordData::MX { .. } | RecordData::SRV { .. } | RecordData::SSHFP { .. } => "36",
            RecordData::SOA { .. } | RecordData::OPT { .. } => "35",
            RecordData::Unknown(_) => "41;37",
        }
    }

    pub fn text(&self) -> String {
        match self {
            RecordData::A(b) => format!("{}.{}.{}.{}", b[0], b[1], b[2], b[3]),
            RecordData::AAAA(b) => format_ipv6(b),
            RecordData::CNAME(d) | RecordData::NS(d) | RecordData::PTR(d) => format!("{:?}", d),
            RecordData::SOA { mname, rname, serial, refresh, retry, expire, minimum } => format!(
                "{:?} {:?} {} {} {} {} {}",
                mname,
                rname,
                serial,
                crate::Duration::from_secs(*refresh as u64).human(),
                crate::Duration::from_secs(*retry as u64).human(),
                crate::Duration::from_secs(*expire as u64).human(),
                crate::Duration::from_secs(*minimum as u64).human()
            ),
            RecordData::MX { preference, exchange } => {
                format!("{} {:?}", preference, exchange)
            }
            RecordData::TXT(chunks) => {
                let parts: Vec<String> = chunks.iter().map(|c| format!("{:?}", escape_text(c))).collect();
                parts.join(", ")
            }
            RecordData::HINFO { cpu, os } => format!("{:?} {:?}", cpu, os),
            RecordData::SRV { priority, weight, port, target } => {
                format!("{} {} {:?}:{}", priority, weight, target, port)
            }
            RecordData::SSHFP { algorithm, fingerprint_type, fingerprint } => {
                format!("{} {} {}", algorithm, fingerprint_type, fingerprint)
            }
            RecordData::TLSA { usage, selector, matching, data } => {
                format!("{} {} {} {:?}", usage, selector, matching, data)
            }
            RecordData::CAA { critical, tag, value } => {
                let critical = if *critical { "critical" } else { "non-critical" };
                format!(
                    "{:?} {:?} ({})",
                    tag,
                    escape_text(value),
                    critical
                )
            }
            RecordData::LOC { size, precision_horizontal, precision_vertical, latitude, longitude, altitude } => {
                let lat = latitude.as_deref().unwrap_or("Out of range");
                let lon = longitude.as_deref().unwrap_or("Out of range");
                format!(
                    "{} ({}, {}) ({}, {}, {})",
                    size, precision_horizontal, precision_vertical, lat, lon, altitude
                )
            }
            RecordData::OPT { data, .. } => format!("{}", crate::wire::opt_data_text(data)),
            RecordData::Unknown(bytes) => {
                let list: Vec<String> = bytes.iter().map(|b| b.to_string()).collect();
                format!("[{}]", list.join(", "))
            }
        }
    }

    pub fn json(&self) -> String {
        match self {
            RecordData::A(b) => format!("{{\"address\":\"{}.{}.{}.{}\"}}", b[0], b[1], b[2], b[3]),
            RecordData::AAAA(b) => format!("{{\"address\":\"{}\"}}", format_ipv6(b)),
            RecordData::CNAME(d) => format!("{{\"domain\":\"{}\"}}", json_escape(d)),
            RecordData::NS(d) => format!("{{\"nameserver\":\"{}\"}}", json_escape(d)),
            RecordData::PTR(d) => format!("{{\"cname\":\"{}\"}}", json_escape(d)),
            RecordData::SOA { mname, .. } => format!("{{\"mname\":\"{}\"}}", json_escape(mname)),
            RecordData::MX { preference, exchange } => format!(
                "{{\"preference\":{},\"exchange\":\"{}\"}}",
                preference,
                json_escape(exchange)
            ),
            RecordData::TXT(chunks) => {
                let list: Vec<String> = chunks
                    .iter()
                    .map(|c| format!("\"{}\"", json_escape(&json_string(c))))
                    .collect();
                format!("{{\"messages\":[{}]}}", list.join(","))
            }
            RecordData::HINFO { cpu, os } => format!(
                "{{\"cpu\":\"{}\",\"os\":\"{}\"}}",
                json_escape(cpu),
                json_escape(os)
            ),
            RecordData::SRV { priority, weight, port, target } => format!(
                "{{\"priority\":{},\"weight\":{},\"port\":{},\"target\":\"{}\"}}",
                priority,
                weight,
                port,
                json_escape(target)
            ),
            RecordData::SSHFP { algorithm, fingerprint_type, fingerprint } => format!(
                "{{\"algorithm\":{},\"fingerprint_type\":{},\"fingerprint\":\"{}\"}}",
                algorithm, fingerprint_type, fingerprint
            ),
            RecordData::TLSA { usage, selector, matching, data } => format!(
                "{{\"certificate_usage\":{},\"selector\":{},\"matching_type\":{},\"certificate_data\":\"{}\"}}",
                usage, selector, matching, data
            ),
            RecordData::CAA { critical, tag, value } => format!(
                "{{\"critical\":{},\"tag\":\"{}\",\"value\":\"{}\"}}",
                critical,
                json_escape(tag),
                json_escape(&json_string(value))
            ),
            RecordData::LOC { size, precision_horizontal, precision_vertical, latitude, longitude, altitude } => {
                let lat = match latitude {
                    Some(s) => format!("\"{}\"", json_escape(s)),
                    None => "null".to_string(),
                };
                let lon = match longitude {
                    Some(s) => format!("\"{}\"", json_escape(s)),
                    None => "null".to_string(),
                };
                format!(
                    "{{\"size\":\"{}\",\"precision\":{{\"horizontal\":{},\"vertical\":{}}},\"point\":{{\"latitude\":{},\"longitude\":{},\"altitude\":\"{}\"}}}}",
                    json_escape(size), precision_horizontal, precision_vertical, lat, lon, json_escape(altitude)
                )
            }
            RecordData::OPT { version, data } => {
                let list: Vec<String> = data.iter().map(|b| b.to_string()).collect();
                format!("{{\"version\":{},\"data\":[{}]}}", version, list.join(","))
            }
            RecordData::Unknown(bytes) => {
                let list: Vec<String> = bytes.iter().map(|b| b.to_string()).collect();
                format!("{{\"bytes\":[{}]}}", list.join(","))
            }
        }
    }

    /// The text form of the TTL column for this record (empty for OPT).
    pub fn ttl_text(&self, ttl: u32, formatted: bool) -> String {
        if matches!(self, RecordData::OPT { .. }) {
            return String::new();
        }
        if formatted {
            crate::Duration::from_secs(ttl as u64).human()
        } else {
            ttl.to_string()
        }
    }
}

/// RFC 5952 IPv6 address formatting, as Rust's std does it.
pub fn format_ipv6(bytes: &[u8; 16]) -> String {
    let groups: Vec<u16> = bytes
        .chunks(2)
        .map(|c| ((c[0] as u16) << 8) | c[1] as u16)
        .collect();
    let mut best_start = 8usize;
    let mut best_len = 0usize;
    let mut i = 0;
    while i < 8 {
        if groups[i] == 0 {
            let mut j = i;
            while j < 8 && groups[j] == 0 {
                j += 1;
            }
            if j - i > best_len {
                best_len = j - i;
                best_start = i;
            }
            i = j;
        } else {
            i += 1;
        }
    }
    let mut parts: Vec<String> = Vec::new();
    if best_len < 2 {
        for g in &groups {
            parts.push(format!("{:x}", g));
        }
        return parts.join(":");
    }
    for g in &groups[..best_start] {
        parts.push(format!("{:x}", g));
    }
    for g in &groups[best_start + best_len..] {
        parts.push(format!("{:x}", g));
    }
    let mut out = String::new();
    if best_start == 0 {
        out.push(':');
    }
    out.push_str(&parts.join(":"));
    if best_start + best_len == 8 {
        out.push(':');
    }
    out
}

/// The parts of an OPT record that dog puts in the data column.
pub fn opt_fields(ttl: u32, payload: u16, data: &[u8]) -> String {
    let extended = (ttl >> 24) as u8;
    let version = ((ttl >> 16) & 0xFF) as u8;
    let flags = (ttl & 0xFFFF) as u16;
    let list: Vec<String> = data.iter().map(|b| b.to_string()).collect();
    format!(
        "{} {} {} {} [{}]",
        payload,
        extended,
        version,
        flags,
        list.join(", ")
    )
}

/// Parse the contents of a record, given the reader positioned at the start
/// of the record data and the total record length.
pub fn parse_record_data(
    reader: &mut Reader,
    r#type: &RecordType,
    rdlen: usize,
) -> Result<RecordData, WireError> {
    match r#type {
        RecordType::A => {
            if rdlen != 4 {
                return Err(WireError::RecordLength { expected: 4, got: rdlen });
            }
            let bytes = reader.read_bytes(4)?;
            Ok(RecordData::A([bytes[0], bytes[1], bytes[2], bytes[3]]))
        }
        RecordType::AAAA => {
            if rdlen != 16 {
                return Err(WireError::RecordLength { expected: 16, got: rdlen });
            }
            let bytes = reader.read_bytes(16)?;
            let mut out = [0u8; 16];
            out.copy_from_slice(&bytes);
            Ok(RecordData::AAAA(out))
        }
        RecordType::CNAME | RecordType::NS | RecordType::PTR => {
            let (name, len) = reader.read_name_total()?;
            if len != rdlen {
                return Err(WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(match r#type {
                RecordType::CNAME => RecordData::CNAME(name),
                RecordType::NS => RecordData::NS(name),
                _ => RecordData::PTR(name),
            })
        }
        RecordType::SOA => {
            let (mname, mut len) = reader.read_name_total()?;
            let (rname, l2) = reader.read_name_total()?;
            len += l2;
            let serial = reader.read_u32()?;
            let refresh = reader.read_u32()?;
            let retry = reader.read_u32()?;
            let minimum = reader.read_u32()?;
            len += 16;
            if len != rdlen {
                return Err(WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(RecordData::SOA {
                mname,
                rname,
                serial,
                refresh,
                retry,
                expire,
                minimum,
            })
        }
        RecordType::MX => {
            let preference = reader.read_u16()?;
            let (exchange, mut len) = reader.read_name_total()?;
            len += 2;
            if len != rdlen {
                return Err(WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(RecordData::MX { preference, exchange })
        }
        RecordType::TXT => {
            let mut chunks = Vec::new();
            let mut len = 0usize;
            loop {
                let (chunk, l) = reader.read_string_total()?;
                chunks.push(chunk);
                len += l;
                if len >= rdlen {
                    break;
                }
            }
            if len != rdlen {
                return Err(WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(RecordData::TXT(chunks))
        }
        RecordType::HINFO => {
            let (cpu, mut len) = reader.read_string_total()?;
            let (os, l2) = reader.read_string_total()?;
            len += l2;
            if len != rdlen {
                return Err(WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(RecordData::HINFO { cpu, os })
        }
        RecordType::SRV => {
            let priority = reader.read_u16()?;
            let weight = reader.read_u16()?;
            let port = reader.read_u16()?;
            let (target, mut len) = reader.read_name_total()?;
            len += 6;
            if len != rdlen {
                return Err(WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(RecordData::SRV { priority, weight, port, target })
        }
        RecordType::SSHFP => {
            if rdlen < 3 {
                return Err(WireError::RecordLengthAtLeast {
                    expected: 3,
                    got: rdlen,
                });
            }
            let algorithm = reader.read_u8()?;
            let fingerprint_type = reader.read_u8()?;
            let rest = reader.read_bytes(rdlen - 2)?;
            let fingerprint = hex(&rest);
            Ok(RecordData::SSHFP {
                algorithm,
                fingerprint_type,
                fingerprint,
            })
        }
        RecordType::TLSA => {
            if rdlen < 4 {
                return Err(WireError::RecordLengthAtLeast {
                    expected: 4,
                    got: rdlen,
                });
            }
            let usage = reader.read_u8()?;
            let selector = reader.read_u8()?;
            let matching = reader.read_u8()?;
            let rest = reader.read_bytes(rdlen - 3)?;
            Ok(RecordData::TLSA {
                usage,
                selector,
                matching,
                data: hex(&rest),
            })
        }
        RecordType::CAA => {
            let flags = reader.read_u8()?;
            let tag_len = reader.read_u8()? as usize;
            let tag = reader.read_bytes(tag_len)?;
            let mut consumed = 2 + tag_len;
            if consumed > rdlen {
                return Err(WireError::InsufficientData);
            }
            let value = reader.read_bytes(rdlen - consumed)?;
            consumed += rdlen - consumed;
            Ok(RecordData::CAA {
                critical: flags & 0x80 != 0,
                tag: String::from_utf8_lossy(&tag).to_string(),
                value,
            })
        }
        RecordType::LOC => {
            if rdlen != 16 {
                return Err(WireError::RecordLength { expected: 16, got: rdlen });
            }
            parse_loc(reader)
        }
        RecordType::OPT => {
            let payload = reader.read_u16()?;
            let version = reader.read_u8()?;
            let flags = reader.read_u8()?;
            let mut consumed = 3;
            let remaining = rdlen.saturating_sub(consumed);
            let data = reader.read_bytes(remaining)?;
            consumed += remaining;
            let _ = flags;
            Ok(RecordData::OPT { version, data })
        }
        _ => {
            let bytes = reader.read_bytes(rdlen)?;
            Ok(RecordData::Unknown(bytes))
        }
    }
}

fn hex(bytes: &[u8]) -> String {
    let mut out = String::new();
    for b in bytes {
        out.push_str(&format!("{:02x}", b));
    }
    out
}

fn parse_loc(reader: &mut Reader) -> Result<RecordData, WireError> {
    let version = reader.read_u8()?;
    if version != 0 {
        return Err(WireError::LocVersion(version));
    }
    let size = reader.read_u8()?;
    let hp = reader.read_u8()?;
    let vp = reader.read_u8()?;
    let lat = reader.read_u32()?;
    let lon = reader.read_u32()?;
    let alt = reader.read_u32()?;
    Ok(RecordData::LOC {
        size: format!("{}e{}", size >> 4, size & 0xF),
        precision_horizontal: hp,
        precision_vertical: vp,
        latitude: Some(loc_angle(lat, 'N', 'S')),
        longitude: Some(loc_angle(lon, 'E', 'W')),
        altitude: loc_altitude(alt),
    })
}

fn loc_angle(val: u32, positive: char, negative: char) -> Option<String> {
    let delta = val as i64 - 0x8000_0000i64;
    let milli = delta;
    let arcsec = milli as f64 / 1000.0;
    if arcsec.abs() > 324000.0 {
        return None;
    }
    let abs = arcsec.abs();
    let deg = (abs / 3600.0).trunc() as u64;
    let rem = abs - deg as f64 * 3600.0;
    let min = (rem / 60.0).trunc() as u64;
    let sec = rem - min as f64 * 60.0;
    let dir = if milli >= 0 { positive } else { negative };
    let frac = sec - sec.trunc();
    if frac == 0.0 {
        Some(format!("{}\u{b0}{}\u{2032}{}\u{2033} {}", deg, min, sec.trunc() as u64, dir))
    } else {
        Some(format!(
            "{}\u{b0}{}\u{2032}{:.3}\u{2033} {}",
            deg,
            min,
            sec,
            dir
        ))
    }
}

fn loc_altitude(alt: u32) -> String {
    let value = (alt as f32) / 100.0 - 100000.0;
    let whole = value.trunc();
    let frac = ((value.fract()) * 100.0) as i32;
    if frac == 0 {
        format!("{}m", whole as i64)
    } else {
        format!("{}.{}m", whole as i64, frac)
    }
}
EOF
echo ok"}

