//! Reading and writing DNS packets.

use crate::name::{Labels, WireError};
use crate::records::{opt_fields, parse_record_data, RecordData, RecordType};
use crate::Class;

/// A DNS message section marker, used to colour rows.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Section {
    Answer,
    Authority,
    Additional,
}

impl Section {
    pub fn marker(&self) -> &'static str {
        match self {
            Section::Answer => "",
            Section::Authority => "A",
            Section::Additional => "+",
        }
    }

    pub fn marker_colour(&self) -> &'static str {
        match self {
            Section::Answer => "",
            Section::Authority => "36",
            Section::Additional => "32",
        }
    }
}

/// A single record as read off the wire.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Record {
    pub name: String,
    pub class: Class,
    pub ttl: u32,
    pub data: RecordData,
    pub section: Section,
}

impl Record {
    pub fn type_name(&self) -> String {
        match &self.data {
            RecordData::Unknown(_) => RecordType::from_number(0).name(),
            _ => self.data.type_name(),
        }
    }

    pub fn type_number(&self) -> u16 {
        match &self.data {
            RecordData::A(_) => 1,
            RecordData::AAAA(_) => 28,
            RecordData::CNAME(_) => 5,
            RecordData::NS(_) => 2,
            RecordData::PTR(_) => 12,
            RecordData::SOA { .. } => 6,
            RecordData::MX { .. } => 15,
            RecordData::TXT(_) => 16,
            RecordData::HINFO { .. } => 13,
            RecordData::SRV { .. } => 33,
            RecordData::SSHFP { .. } => 44,
            RecordData::TLSA { .. } => 52,
            RecordData::CAA { .. } => 257,
            RecordData::LOC { .. } => 29,
            RecordData::OPT { .. } => 41,
            RecordData::Unknown(_) => self.num,
        }
    }

    pub fn json(&self) -> String {
        let mut out = String::new();
        out.push_str("{\"name\":");
        out.push_str(&json_string(&self.name));
        if matches!(self.data, RecordData::OPT { .. }) {
            out.push_str(",\"type\":\"OPT\"");
        } else {
            let name = self.data.type_name();
            if name.is_empty() {
                out.push_str(&format!(",\"type\":{}", self.num));
            } else {
                out.push_str(",\"type\":");
                out.push_str(&json_string(&name));
            }
            out.push_str(",\"class\":");
            out.push_str(&json_string(&self.class.name()));
            out.push_str(&format!(",\"ttl\":{}", self.ttl));
        }
        out.push_str(",\"data\":");
        out.push_str(&self.data.json());
        out.push('}');
        out
    }
}

// A helper field is needed for unknown types; store it alongside.
pub fn json_string(s: &str) -> String {
    let mut out = String::new();
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{08}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{0c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

pub fn opt_data_text(data: &[u8]) -> String {
    let list: Vec<String> = data.iter().map(|b| b.to_string()).collect();
    format!("[{}]", list.join(", "))
}

/// Reader over a packet, with dog's rules about how far reads may go.
pub struct Reader<'a> {
    pub buf: &'a [u8],
    pub pos: usize,
}

impl<'a> Reader<'a> {
    pub fn new(buf: &'a [u8], pos: usize) -> Self {
        Reader { buf, pos }
    }

    pub fn remaining(&self) -> usize {
        self.buf.len().saturating_sub(self.pos)
    }

    pub fn read_u8(&mut self) -> Result<u8, WireError> {
        if self.pos >= self.buf.len() {
            return Err(WireError::InsufficientData);
        }
        let b = self.buf[self.pos];
        self.pos += 1;
        Ok(b)
    }

    pub fn read_u16(&mut self) -> Result<u16, WireError> {
        let a = self.read_u8()? as u16;
        let b = self.read_u8()? as u16;
        Ok((a << 8) | b)
    }

    pub fn read_u32(&mut self) -> Result<u32, WireError> {
        let a = self.read_u16()? as u32;
        let b = self.read_u16()? as u32;
        Ok((a << 16) | b)
    }

    pub fn read_bytes(&mut self, n: usize) -> Result<Vec<u8>, WireError> {
        if self.remaining() < n {
            return Err(WireError::InsufficientData);
        }
        let out = self.buf[self.pos..self.pos + n].to_vec();
        self.pos += n;
        Ok(out)
    }

    /// Read a domain name, returning the name and how many bytes it took up.
    pub fn read_name_total(&mut self) -> Result<(String, usize), WireError> {
        let start = self.pos;
        let mut labels = Labels::new();
        let mut recursion = 0usize;
        let mut jump: Option<usize> = None;
        let mut cur = self.pos;
        loop {
            recursion += 1;
            if recursion > 128 {
                return Err(WireError::TooMuchRecursion(cur));
            }
            if cur >= self.buf.len() {
                return Err(WireError::InsufficientData);
            }
            let len = self.buf[cur] as usize;
            if len == 0 {
                cur += 1;
                break;
            }
            if len & 0xC0 == 0xC0 {
                if cur + 1 >= self.buf.len() {
                    return Err(WireError::InsufficientData);
                }
                let target = ((len as usize & 0x3F) << 8) | self.buf[cur + 1] as usize;
                if jump.is_none() {
                    jump = Some(cur);
                }
                if target >= self.buf.len() {
                    return Err(WireError::InsufficientData);
                }
                cur = target;
                continue;
            }
            if cur + 1 + len > self.buf.len() {
                return Err(WireError::InsufficientData);
            }
            let label = String::from_utf8_lossy(&self.buf[cur + 1..cur + 1 + len]).to_string();
            labels.segments.push((label.len(), label));
            cur += 1 + len;
        }
        let total = if let Some(j) = jump { j + 2 - start } else { cur - start };
        self.pos = if let Some(j) = jump { j + 2 } else { cur };
        Ok((labels.to_string(), total))
    }

    /// Read a length-prefixed string, returning it and the bytes it took up.
    pub fn read_string_total(&mut self) -> Result<(Vec<u8>, usize), WireError> {
        let len = self.read_u8()? as usize;
        let bytes = self.read_bytes(len)?;
        Ok((bytes, len + 1))
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Flags {
    pub response: bool,
    pub op_code: u8,
    pub authoritative: bool,
    pub truncated: bool,
    pub recursion_desired: bool,
    pub recursion_available: bool,
    pub authentic_data: bool,
    pub checking_disabled: bool,
    pub error_code: u8,
}

/// A complete DNS message.
#[derive(Clone, Debug)]
pub struct Message {
    pub txid: u16,
    pub flags: Flags,
    pub queries: Vec<(Labels, RecordType, Class)>,
    pub answers: Vec<Record>,
    pub authorities: Vec<Record>,
    pub additionals: Vec<Record>,
}

impl Message {
    /// Build a query packet.
    pub fn build_query(
        txid: u16,
        name: &Labels,
        r#type: &RecordType,
        class: &Class,
        edns: bool,
        udp_payload_size: u16,
        authoritative: bool,
        authentic: bool,
        checking_disabled: bool,
    ) -> Vec<u8> {
        let mut flags: u16 = 0x0100;
        if authoritative {
            flags |= 0x0400;
        }
        if authentic {
            flags |= 0x0020;
        }
        if checking_disabled {
            flags |= 0x0010;
        }
        let mut out = Vec::new();
        out.extend_from_slice(&txid.to_be_bytes());
        out.extend_from_slice(&flags.to_be_bytes());
        out.extend_from_slice(&1u16.to_be_bytes());
        out.extend_from_slice(&0u16.to_be_bytes());
        out.extend_from_slice(&0u16.to_be_bytes());
        out.extend_from_slice(&(if edns { 1u16 } else { 0u16 }).to_be_bytes());
        out.extend_from_slice(&name.bytes());
        out.extend_from_slice(&r#type.number().to_be_bytes());
        out.extend_from_slice(&class.number().to_be_bytes());
        if edns {
            out.push(0);
            out.extend_from_slice(&41u16.to_be_bytes());
            out.extend_from_slice(&udp_payload_size.to_be_bytes());
            out.extend_from_slice(&0u32.to_be_bytes());
            out.extend_from_slice(&0u16.to_be_bytes());
        }
        out
    }

    /// Parse a response packet, following dog's rules.
    pub fn parse(bytes: &[u8]) -> Result<Message, WireError> {
        let mut reader = Reader::new(bytes, 0);
        if reader.remaining() < 12 {
            return Err(WireError::InsufficientData);
        }
        let txid = reader.read_u16()?;
        let flags_raw = reader.read_u16()?;
        let qd = reader.read_u16()? as usize;
        let an = reader.read_u16()? as usize;
        let ns = reader.read_u16()? as usize;
        let ar = reader.read_u16()? as usize;
        let flags = Flags {
            response: flags_raw & 0x8000 != 0,
            op_code: ((flags_raw >> 11) & 0xF) as u8,
            authoritative: flags_raw & 0x0400 != 0,
            truncated: flags_raw & 0x0200 != 0,
            recursion_desired: flags_raw & 0x0100 != 0,
            recursion_available: flags_raw & 0x0080 != 0,
            authentic_data: flags_raw & 0x0020 != 0,
            checking_disabled: flags_raw & 0x0010 != 0,
            error_code: (flags_raw & 0xF) as u8,
        };
        let mut queries = Vec::new();
        for _ in 0..qd {
            let (name, _) = reader.read_name_total()?;
            let tnum = reader.read_u16()?;
            let cnum = reader.read_u16()?;
            queries.push((
                parse_wire_name(&name),
                RecordType::from_number(tnum),
                Class::from_number(cnum),
            ));
        }
        let mut answers = Vec::new();
        let mut authorities = Vec::new();
        let mut additionals = Vec::new();
        let mut records: Vec<(Section, Record)> = Vec::new();
        let mut counts = [(Section::Answer, an), (Section::Authority, ns), (Section::Additional, ar)];
        for (section, count) in counts.iter_mut() {
            for _ in 0..*count {
                let (name, _) = reader.read_name_total()?;
                let tnum = reader.read_u16()?;
                let cnum = reader.read_u16()?;
                let ttl = reader.read_u32()?;
                let rdlen = reader.read_u16()? as usize;
                let payload = cnum;
                let rtype = RecordType::from_number(tnum);
                let data = if tnum == 41 {
                    // OPT: payload size comes from the class field.
                    parse_opt(&mut reader, ttl, rdlen, payload)?
                } else {
                    parse_record_data(&mut reader, &rtype, rdlen)?
                };
                let name_labels = parse_wire_name(&name);
                records.push((
                    *section,
                    Record {
                        name,
                        class: Class::from_number(cnum),
                        ttl,
                        data,
                        section: *section,
                    },
                ));
                let _ = name_labels;
            }
        }
        for (section, record) in records {
            match section {
                Section::Answer => answers.push(record),
                Section::Authority => authorities.push(record),
                Section::Additional => additionals.push(record),
            }
        }
        Ok(Message {
            txid,
            flags,
            queries,
            answers,
            authorities,
            additionals,
        })
    }
}

fn parse_opt(reader: &mut Reader, ttl: u32, rdlen: usize, payload: u16) -> Result<RecordData, WireError> {
    let extended = (ttl >> 24) as u8;
    let version = ((ttl >> 16) & 0xFF) as u8;
    let _flags = (ttl & 0xFFFF) as u16;
    let mut consumed = 0usize;
    let remaining = rdlen.saturating_sub(consumed);
    let data = reader.read_bytes(remaining)?;
    consumed += remaining;
    let _ = extended;
    Ok(RecordData::OPT { version, payload, data })
}

fn parse_wire_name(s: &str) -> Labels {
    let mut labels = Labels::new();
    if s.is_empty() {
        return labels;
    }
    for part in s.trim_end_matches('.').split('.') {
        labels.segments.push((part.len(), part.to_string()));
    }
    labels
}
EOF
echo ok"}

