    let data = reader.read_bytes(remaining)?;
    consumed += remaining;
    let _ = extended;
    Ok(RecordData::OPT { version, payload, data })
}

fn parse_wire_name(s: &str) -> Labels {
    let mut labels = Labels::new();
    if s.is_empty() {
        return labels;
    }
    for part in s.trim_end_matches('.').split('.') {
        labels.segments.push((part.len(), part.to_string()));
    }
    labels
}
