//! Record types and the human-readable / JSON forms of their contents.

use crate::punycode;
use crate::wire::Reader;

/// Record types that dog knows the number of.
#[derive(Clone, PartialEq, Eq, Hash, Debug)]
pub enum RecordType {
    A,
    NS,
    CNAME,
    SOA,
    PTR,
    HINFO,
    MX,
    TXT,
    AAAA,
    LOC,
    SRV,
    OPT,
    SSHFP,
    TLSA,
    CAA,
    Other(OtherType),
}

#[derive(Clone, PartialEq, Eq, Hash, Debug)]
pub enum OtherType {
    HeardOf(String, u16),
    UnheardOf(u16),
}

/// Types whose contents dog can interpret.
pub const KNOWN: &[(u16, &str)] = &[
    (1, "A"),
    (2, "NS"),
    (5, "CNAME"),
    (6, "SOA"),
    (12, "PTR"),
    (13, "HINFO"),
    (15, "MX"),
    (16, "TXT"),
    (28, "AAAA"),
    (29, "LOC"),
    (33, "SRV"),
    (41, "OPT"),
    (44, "SSHFP"),
    (52, "TLSA"),
    (257, "CAA"),
];

/// Types dog has heard of, but cannot interpret.
pub const HEARD_OF: &[(u16, &str)] = &[
    (17, "RP"),
    (18, "AFSDB"),
    (23, "SIG"),
    (25, "KEY"),
    (35, "NAPTR"),
    (36, "KX"),
    (37, "CERT"),
    (43, "DS"),
    (45, "IPSECKEY"),
    (46, "RRSIG"),
    (47, "NSEC"),
    (50, "NSEC3"),
    (51, "NSEC3PARAM"),
    (53, "SMIMEA"),
    (55, "HIP"),
    (61, "OPENPGPKEY"),
    (62, "CSYNC"),
    (249, "TKEY"),
    (251, "IXFR"),
    (252, "AXFR"),
    (254, "APL"),
    (255, "ANY"),
    (32769, "TA"),
    (32770, "DLV"),
];

impl RecordType {
    pub fn number(&self) -> u16 {
        match self {
            RecordType::A => 1,
            RecordType::NS => 2,
            RecordType::CNAME => 5,
            RecordType::SOA => 6,
            RecordType::PTR => 12,
            RecordType::HINFO => 13,
            RecordType::MX => 15,
            RecordType::TXT => 16,
            RecordType::AAAA => 28,
            RecordType::LOC => 29,
            RecordType::SRV => 33,
            RecordType::OPT => 41,
            RecordType::SSHFP => 44,
            RecordType::TLSA => 52,
            RecordType::CAA => 257,
            RecordType::Other(OtherType::HeardOf(_, n)) => *n,
            RecordType::Other(OtherType::UnheardOf(n)) => *n,
        }
    }

    pub fn name(&self) -> String {
        match self {
            RecordType::Other(OtherType::UnheardOf(n)) => n.to_string(),
            other => {
                let num = other.number();
                for &(n, name) in KNOWN.iter().chain(HEARD_OF.iter()) {
                    if n == num {
                        return name.to_string();
                    }
                }
                num.to_string()
            }
        }
    }

    pub fn debug(&self) -> String {
        match self {
            RecordType::Other(OtherType::HeardOf(name, num)) => format!(
                "Other(\n                    HeardOf(\n                        {:?},\n                        {},\n                    ),\n                )",
                name, num
            ),
            RecordType::Other(OtherType::UnheardOf(num)) => format!(
                "Other(\n                    UnheardOf(\n                        {},\n                    ),\n                )",
                num
            ),
            other => other.name(),
        }
    }

    pub fn from_number(num: u16) -> Self {
        for &(n, name) in KNOWN {
            if n == num {
                return from_name(name);
            }
        }
        for &(n, name) in HEARD_OF {
            if n == num {
                return RecordType::Other(OtherType::HeardOf(name.to_string(), num));
            }
        }
        RecordType::Other(OtherType::UnheardOf(num))
    }

    /// Parse a record type given on the command line.
    pub fn parse(text: &str) -> Result<Option<Self>, ()> {
        if text.eq_ignore_ascii_case("OPT") {
            return Err(());
        }
        if let Ok(num) = text.parse::<u16>() {
            return Ok(Some(RecordType::Other(OtherType::UnheardOf(num))));
        }
        for &(_, name) in KNOWN.iter().chain(HEARD_OF.iter()) {
            if text.eq_ignore_ascii_case(name) {
                return Ok(Some(from_name(name)));
            }
        }
        Ok(None)
    }
}

fn from_name(name: &str) -> RecordType {
    match name {
        "A" => RecordType::A,
        "NS" => RecordType::NS,
        "CNAME" => RecordType::CNAME,
        "SOA" => RecordType::SOA,
        "PTR" => RecordType::PTR,
        "HINFO" => RecordType::HINFO,
        "MX" => RecordType::MX,
        "TXT" => RecordType::TXT,
        "AAAA" => RecordType::AAAA,
        "LOC" => RecordType::LOC,
        "SRV" => RecordType::SRV,
        "OPT" => RecordType::OPT,
        "SSHFP" => RecordType::SSHFP,
        "TLSA" => RecordType::TLSA,
        "CAA" => RecordType::CAA,
        other => {
            let num = HEARD_OF
                .iter()
                .find(|(_, n)| *n == other)
                .map(|(n, _)| *n)
                .unwrap_or(0);
            RecordType::Other(OtherType::HeardOf(other.to_string(), num))
        }
    }
}

/// The contents of a DNS record, as dog interprets them.
#[derive(Clone, PartialEq, Eq, Debug)]
pub enum RecordData {
    A([u8; 4]),
    AAAA([u8; 16]),
    CNAME(String),
    NS(String),
    PTR(String),
    SOA {
        mname: String,
        rname: String,
        serial: u32,
        refresh: u32,
        retry: u32,
        expire: u32,
        minimum: u32,
    },
    MX {
        preference: u16,
        exchange: String,
    },
    TXT(Vec<Vec<u8>>),
    HINFO {
        cpu: String,
        os: String,
    },
    SRV {
        priority: u16,
        weight: u16,
        port: u16,
        target: String,
    },
    SSHFP {
        algorithm: u8,
        fingerprint_type: u8,
        fingerprint: String,
    },
    TLSA {
        usage: u8,
        selector: u8,
        matching: u8,
        data: String,
    },
    CAA {
        critical: bool,
        tag: String,
        value: Vec<u8>,
    },
    LOC {
        size: String,
        precision_horizontal: u8,
        precision_vertical: u8,
        latitude: Option<String>,
        longitude: Option<String>,
        altitude: String,
    },
    OPT {
        payload: u16,
        extended_rcode: u8,
        version: u8,
        flags: u16,
        data: Vec<u8>,
    },
    Unknown(Vec<u8>),
}

impl RecordData {
    pub fn type_number(&self) -> u16 {
        match self {
            RecordData::A(_) => 1,
            RecordData::AAAA(_) => 28,
            RecordData::CNAME(_) => 5,
            RecordData::NS(_) => 2,
            RecordData::PTR(_) => 12,
            RecordData::SOA { .. } => 6,
            RecordData::MX { .. } => 15,
            RecordData::TXT(_) => 16,
            RecordData::HINFO { .. } => 13,
            RecordData::SRV { .. } => 33,
            RecordData::SSHFP { .. } => 44,
            RecordData::TLSA { .. } => 52,
            RecordData::CAA { .. } => 257,
            RecordData::LOC { .. } => 29,
            RecordData::OPT { .. } => 41,
            RecordData::Unknown(_) => 0,
        }
    }

    pub fn type_name(&self) -> Option<String> {
        match self {
            RecordData::Unknown(_) => None,
            _ => {
                let num = self.type_number();
                for &(n, name) in KNOWN.iter().chain(HEARD_OF.iter()) {
                    if n == num {
                        return Some(name.to_string());
                    }
                }
                None
            }
        }
    }

    /// The colour code dog paints the record type with.
    pub fn colour(&self) -> &'static str {
        match self {
            RecordData::A(_) | RecordData::AAAA(_) => "1;32",
            RecordData::NS(_) | RecordData::PTR(_) | RecordData::CAA { .. } => "31",
            RecordData::CNAME(_)
            | RecordData::TXT(_)
            | RecordData::HINFO { .. }
            | RecordData::TLSA { .. }
            | RecordData::LOC { .. } => "33",
            RecordData::MX { .. } | RecordData::SRV { .. } | RecordData::SSHFP { .. } => "36",
            RecordData::SOA { .. } | RecordData::OPT { .. } => "35",
            RecordData::Unknown(_) => "41;37",
        }
    }

    pub fn text(&self) -> String {
        match self {
            RecordData::A(b) => format!("{}.{}.{}.{}", b[0], b[1], b[2], b[3]),
            RecordData::AAAA(b) => format_ipv6(b),
            RecordData::CNAME(d) | RecordData::NS(d) | RecordData::PTR(d) => format!("{:?}", d),
            RecordData::SOA { mname, rname, serial, refresh, retry, expire, minimum } => format!(
                "{:?} {:?} {} {} {} {} {}",
                mname,
                rname,
                serial,
                crate::Duration::from_secs(*refresh as u64).human(),
                crate::Duration::from_secs(*retry as u64).human(),
                crate::Duration::from_secs(*expire as u64).human(),
                crate::Duration::from_secs(*minimum as u64).human()
            ),
            RecordData::MX { preference, exchange } => format!("{} {:?}", preference, exchange),
            RecordData::TXT(chunks) => {
                let parts: Vec<String> = chunks
                    .iter()
                    .map(|c| format!("{:?}", escape_text(c)))
                    .collect();
                parts.join(", ")
            }
            RecordData::HINFO { cpu, os } => format!("{:?} {:?}", cpu, os),
            RecordData::SRV { priority, weight, port, target } => {
                format!("{} {} {:?}:{}", priority, weight, target, port)
            }
            RecordData::SSHFP { algorithm, fingerprint_type, fingerprint } => {
                format!("{} {} {}", algorithm, fingerprint_type, fingerprint)
            }
            RecordData::TLSA { usage, selector, matching, data } => {
                format!("{} {} {} {:?}", usage, selector, matching, data)
            }
            RecordData::CAA { critical, tag, value } => {
                let critical = if *critical { "critical" } else { "non-critical" };
                format!("{:?} {:?} ({})", tag, escape_text(value), critical)
            }
            RecordData::LOC { size, precision_horizontal, precision_vertical, latitude, longitude, altitude } => {
                let lat = latitude.as_deref().unwrap_or("Out of range");
                let lon = longitude.as_deref().unwrap_or("Out of range");
                format!(
                    "{} ({}, {}) ({}, {}, {})",
                    size, precision_horizontal, precision_vertical, lat, lon, altitude
                )
            }
            RecordData::OPT { payload, extended_rcode, version, flags, data } => {
                let list: Vec<String> = data.iter().map(|b| b.to_string()).collect();
                format!(
                    "{} {} {} {} [{}]",
                    payload,
                    extended_rcode,
                    version,
                    flags,
                    list.join(", ")
                )
            }
            RecordData::Unknown(bytes) => {
                let list: Vec<String> = bytes.iter().map(|b| b.to_string()).collect();
                format!("[{}]", list.join(", "))
            }
        }
    }

    pub fn json(&self) -> String {
        match self {
            RecordData::A(b) => format!("{{\"address\":\"{}.{}.{}.{}\"}}", b[0], b[1], b[2], b[3]),
            RecordData::AAAA(b) => format!("{{\"address\":\"{}\"}}", format_ipv6(b)),
            RecordData::CNAME(d) => format!("{{\"domain\":\"{}\"}}", json_escape(d)),
            RecordData::NS(d) => format!("{{\"nameserver\":\"{}\"}}", json_escape(d)),
            RecordData::PTR(d) => format!("{{\"cname\":\"{}\"}}", json_escape(d)),
            RecordData::SOA { mname, .. } => format!("{{\"mname\":\"{}\"}}", json_escape(mname)),
            RecordData::MX { preference, exchange } => format!(
                "{{\"preference\":{},\"exchange\":\"{}\"}}",
                preference,
                json_escape(exchange)
            ),
            RecordData::TXT(chunks) => {
                let list: Vec<String> = chunks
                    .iter()
                    .map(|c| format!("\"{}\"", json_escape(&String::from_utf8_lossy(c))))
                    .collect();
                format!("{{\"messages\":[{}]}}", list.join(","))
            }
            RecordData::HINFO { cpu, os } => format!(
                "{{\"cpu\":\"{}\",\"os\":\"{}\"}}",
                json_escape(cpu),
                json_escape(os)
            ),
            RecordData::SRV { priority, weight, port, target } => format!(
                "{{\"priority\":{},\"weight\":{},\"port\":{},\"target\":\"{}\"}}",
                priority,
                weight,
                port,
                json_escape(target)
            ),
            RecordData::SSHFP { algorithm, fingerprint_type, fingerprint } => format!(
                "{{\"algorithm\":{},\"fingerprint_type\":{},\"fingerprint\":\"{}\"}}",
                algorithm, fingerprint_type, fingerprint
            ),
            RecordData::TLSA { usage, selector, matching, data } => format!(
                "{{\"certificate_usage\":{},\"selector\":{},\"matching_type\":{},\"certificate_data\":\"{}\"}}",
                usage, selector, matching, data
            ),
            RecordData::CAA { critical, tag, value } => format!(
                "{{\"critical\":{},\"tag\":\"{}\",\"value\":\"{}\"}}",
                critical,
                json_escape(tag),
                json_escape(&String::from_utf8_lossy(value))
            ),
            RecordData::LOC { size, precision_horizontal, precision_vertical, latitude, longitude, altitude } => {
                let lat = match latitude {
                    Some(s) => format!("\"{}\"", json_escape(s)),
                    None => "null".to_string(),
                };
                let lon = match longitude {
                    Some(s) => format!("\"{}\"", json_escape(s)),
                    None => "null".to_string(),
                };
                format!(
                    "{{\"size\":\"{}\",\"precision\":{{\"horizontal\":{},\"vertical\":{}}},\"point\":{{\"latitude\":{},\"longitude\":{},\"altitude\":\"{}\"}}}}",
                    json_escape(size),
                    precision_horizontal,
                    precision_vertical,
                    lat,
                    lon,
                    json_escape(altitude)
                )
            }
            RecordData::OPT { version, data, .. } => {
                let list: Vec<String> = data.iter().map(|b| b.to_string()).collect();
                format!("{{\"version\":{},\"data\":[{}]}}", version, list.join(","))
            }
            RecordData::Unknown(bytes) => {
                let list: Vec<String> = bytes.iter().map(|b| b.to_string()).collect();
                format!("{{\"bytes\":[{}]}}", list.join(","))
            }
        }
    }
}

pub fn escape_text(bytes: &[u8]) -> String {
    let mut out = String::new();
    for &b in bytes {
        if b == b'"' {
            out.push('\\');
            out.push('"');
        } else if b == b'\\' {
            out.push('\\');
            out.push('\\');
        } else if b < 0x20 || b > 0x7F {
            out.push('\\');
            out.push_str(&b.to_string());
        } else {
            out.push(b as char);
        }
    }
    out
}

pub fn json_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{08}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{0c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

/// RFC 5952 IPv6 address formatting, as Rust's standard library does it.
pub fn format_ipv6(bytes: &[u8; 16]) -> String {
    let groups: Vec<u16> = bytes
        .chunks(2)
        .map(|c| ((c[0] as u16) << 8) | c[1] as u16)
        .collect();
    let mut best_start = 8usize;
    let mut best_len = 0usize;
    let mut i = 0;
    while i < 8 {
        if groups[i] == 0 {
            let mut j = i;
            while j < 8 && groups[j] == 0 {
                j += 1;
            }
            if j - i > best_len {
                best_len = j - i;
                best_start = i;
            }
            i = j;
        } else {
            i += 1;
        }
    }
    if best_len < 2 {
        let parts: Vec<String> = groups.iter().map(|g| format!("{:x}", g)).collect();
        return parts.join(":");
    }
    let head: Vec<String> = groups[..best_start].iter().map(|g| format!("{:x}", g)).collect();
    let tail: Vec<String> = groups[best_start + best_len..]
        .iter()
        .map(|g| format!("{:x}", g))
        .collect();
    let mut out = String::new();
    out.push_str(&head.join(":"));
    if !head.is_empty() {
        out.push(':');
    }
    out.push(':');
    if !tail.is_empty() {
        out.push_str(&tail.join(":"));
    }
    out
}

fn hex(bytes: &[u8]) -> String {
    let mut out = String::new();
    for b in bytes {
        out.push_str(&format!("{:02x}", b));
    }
    out
}

/// Parse the contents of a record. `reader` is positioned at the start of the
/// record data; `rdlen` is the length the packet claims for the record.
pub fn parse_record_data(
    reader: &mut Reader,
    num: u16,
    rdlen: usize,
) -> Result<RecordData, crate::name::WireError> {
    match num {
        1 => {
            if rdlen != 4 {
                return Err(crate::name::WireError::RecordLength { expected: 4, got: rdlen });
            }
            let bytes = reader.read_bytes(4)?;
            Ok(RecordData::A([bytes[0], bytes[1], bytes[2], bytes[3]]))
        }
        28 => {
            if rdlen != 16 {
                return Err(crate::name::WireError::RecordLength { expected: 16, got: rdlen });
            }
            let bytes = reader.read_bytes(16)?;
            let mut out = [0u8; 16];
            out.copy_from_slice(&bytes);
            Ok(RecordData::AAAA(out))
        }
        2 | 5 | 12 => {
            let (name, len) = reader.read_name_total()?;
            if len != rdlen {
                return Err(crate::name::WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(match num {
                2 => RecordData::NS(name),
                5 => RecordData::CNAME(name),
                _ => RecordData::PTR(name),
            })
        }
        6 => {
            let (mname, mut len) = reader.read_name_total()?;
            let (rname, l2) = reader.read_name_total()?;
            len += l2;
            let serial = reader.read_u32()?;
            let refresh = reader.read_u32()?;
            let retry = reader.read_u32()?;
            let expire = reader.read_u32()?;
            let minimum = reader.read_u32()?;
            len += 20;
            if len != rdlen {
                return Err(crate::name::WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(RecordData::SOA {
                mname,
                rname,
                serial,
                refresh,
                retry,
                expire,
                minimum,
            })
        }
        15 => {
            let preference = reader.read_u16()?;
            let (exchange, mut len) = reader.read_name_total()?;
            len += 2;
            if len != rdlen {
                return Err(crate::name::WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(RecordData::MX { preference, exchange })
        }
        16 => {
            let mut chunks = Vec::new();
            let mut len = 0usize;
            loop {
                let (chunk, l) = reader.read_string_total()?;
                chunks.push(chunk);
                len += l;
                if len >= rdlen {
                    break;
                }
            }
            if len != rdlen {
                return Err(crate::name::WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(RecordData::TXT(chunks))
        }
        13 => {
            let (cpu, mut len) = reader.read_string_total()?;
            let (os, l2) = reader.read_string_total()?;
            len += l2;
            if len != rdlen {
                return Err(crate::name::WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(RecordData::HINFO {
                cpu: String::from_utf8_lossy(&cpu).to_string(),
                os: String::from_utf8_lossy(&os).to_string(),
            })
        }
        33 => {
            let priority = reader.read_u16()?;
            let weight = reader.read_u16()?;
            let port = reader.read_u16()?;
            let (target, mut len) = reader.read_name_total()?;
            len += 6;
            if len != rdlen {
                return Err(crate::name::WireError::SpecifiedLength {
                    specified: rdlen,
                    read: len,
                });
            }
            Ok(RecordData::SRV {
                priority,
                weight,
                port,
                target,
            })
        }
        44 => {
            if rdlen < 3 {
                return Err(crate::name::WireError::RecordLengthAtLeast {
                    expected: 3,
                    got: rdlen,
                });
            }
            let algorithm = reader.read_u8()?;
            let fingerprint_type = reader.read_u8()?;
            let rest = reader.read_bytes(rdlen - 2)?;
            Ok(RecordData::SSHFP {
                algorithm,
                fingerprint_type,
                fingerprint: hex(&rest),
            })
        }
        52 => {
            if rdlen < 4 {
                return Err(crate::name::WireError::RecordLengthAtLeast {
                    expected: 4,
                    got: rdlen,
                });
            }
            let usage = reader.read_u8()?;
            let selector = reader.read_u8()?;
            let matching = reader.read_u8()?;
            let rest = reader.read_bytes(rdlen - 3)?;
            Ok(RecordData::TLSA {
                usage,
                selector,
                matching,
                data: hex(&rest),
            })
        }
        257 => {
            let flags = reader.read_u8()?;
            let tag_len = reader.read_u8()? as usize;
            let tag = reader.read_bytes(tag_len)?;
            let mut consumed = 2 + tag_len;
            if consumed > rdlen {
                return Err(crate::name::WireError::InsufficientData);
            }
            let value = reader.read_bytes(rdlen - consumed)?;
            consumed += value.len();
            let _ = consumed;
            Ok(RecordData::CAA {
                critical: flags & 0x80 != 0,
                tag: String::from_utf8_lossy(&tag).to_string(),
                value,
            })
        }
        29 => parse_loc(reader),
        41 => unreachable!("OPT is handled by the caller"),
        _ => {
            let bytes = reader.read_bytes(rdlen)?;
            Ok(RecordData::Unknown(bytes))
        }
    }
}

/// Parse an OPT record's contents: the payload size comes from the class field.
pub fn parse_opt_data(
    reader: &mut Reader,
    ttl: u32,
    rdlen: usize,
    payload: u16,
) -> Result<RecordData, crate::name::WireError> {
    let extended_rcode = (ttl >> 24) as u8;
    let version = ((ttl >> 16) & 0xFF) as u8;
    let flags = (ttl & 0xFFFF) as u16;
    let remaining = rdlen;
    let data = reader.read_bytes(remaining)?;
    Ok(RecordData::OPT {
        payload,
        extended_rcode,
        version,
        flags,
        data,
    })
}

fn parse_loc(reader: &mut Reader) -> Result<RecordData, crate::name::WireError> {
    let version = reader.read_u8()?;
    if version != 0 {
        return Err(crate::name::WireError::LocVersion(version));
    }
    let size = reader.read_u8()?;
    let hp = reader.read_u8()?;
    let vp = reader.read_u8()?;
    let lat = reader.read_u32()?;
    let lon = reader.read_u32()?;
    let alt = reader.read_u32()?;
    Ok(RecordData::LOC {
        size: format!("{}e{}", size >> 4, size & 0xF),
        precision_horizontal: hp,
        precision_vertical: vp,
        latitude: loc_angle(lat, 'N', 'S'),
        longitude: loc_angle(lon, 'E', 'W'),
        altitude: loc_altitude(alt),
    })
}

fn loc_angle(val: u32, positive: char, negative: char) -> Option<String> {
    let delta = val as i64 - 0x8000_0000i64;
    let arcsec = delta as f64 / 1000.0;
    if arcsec.abs() > 324000.0 {
        return None;
    }
    let abs = arcsec.abs();
    let deg = (abs / 3600.0).trunc() as u64;
    let rem = abs - deg as f64 * 3600.0;
    let min = (rem / 60.0).trunc() as u64;
    let sec = rem - min as f64 * 60.0;
    let dir = if delta >= 0 { positive } else { negative };
    let whole_sec = sec.trunc() as u64;
    let frac = sec - sec.trunc();
    if frac == 0.0 {
        Some(format!(
            "{}\u{b0}{}\u{2032}{}\u{2033} {}",
            deg, min, whole_sec, dir
        ))
    } else {
        Some(format!(
            "{}\u{b0}{}\u{2032}{:.3}\u{2033} {}",
            deg, min, sec, dir
        ))
    }
}

fn loc_altitude(alt: u32) -> String {
    let value = (alt as f32) / 100.0 - 100000.0;
    let whole = value.trunc() as i64;
    let frac = (value.fract() * 100.0) as i32;
    if frac == 0 {
        format!("{}m", whole)
    } else {
        format!("{}.{}m", whole, frac)
    }
}

/// Encode a domain name for the wire.
pub fn labels_bytes(labels: &crate::name::Labels) -> Vec<u8> {
    let mut out = Vec::new();
    for (_, seg) in &labels.segments {
        out.push(seg.len() as u8);
        out.extend_from_slice(seg.as_bytes());
    }
    out.push(0);
    out
}
