/// Reader over a packet. dog reads past record boundaries for names and
/// numbers, but keeps string lists inside the record.
pub struct Reader<'a> {
    pub buf: &'a [u8],
    pub pos: usize,
}

impl<'a> Reader<'a> {
    pub fn new(buf: &'a [u8], pos: usize) -> Self {
        Reader { buf, pos }
    }

    pub fn remaining(&self) -> usize {
        self.buf.len().saturating_sub(self.pos)
    }

    pub fn read_u8(&mut self) -> Result<u8, WireError> {
        if self.pos >= self.buf.len() {
            return Err(WireError::InsufficientData);
        }
        let b = self.buf[self.pos];
        self.pos += 1;
        Ok(b)
    }

    pub fn read_u16(&mut self) -> Result<u16, WireError> {
        let a = self.read_u8()? as u16;
        let b = self.read_u8()? as u16;
        Ok((a << 8) | b)
    }

    pub fn read_u32(&mut self) -> Result<u32, WireError> {
        let a = self.read_u16()? as u32;
        let b = self.read_u16()? as u32;
        Ok((a << 16) | b)
    }

    pub fn read_bytes(&mut self, n: usize) -> Result<Vec<u8>, WireError> {
        if self.remaining() < n {
            return Err(WireError::InsufficientData);
        }
        let out = self.buf[self.pos..self.pos + n].to_vec();
        self.pos += n;
        Ok(out)
    }

    /// Read a domain name; returns the display form and the bytes consumed.
    pub fn read_name_total(&mut self) -> Result<(String, usize), WireError> {
        let start = self.pos;
        let mut labels = Labels::new();
        let mut recursion = 0usize;
        let mut jump: Option<usize> = None;
        let mut cur = self.pos;
        loop {
            recursion += 1;
            if recursion > 128 {
                return Err(WireError::TooMuchRecursion(cur));
            }
            if cur >= self.buf.len() {
                return Err(WireError::InsufficientData);
            }
            let len = self.buf[cur] as usize;
            if len == 0 {
                cur += 1;
                break;
            }
            if len & 0xC0 == 0xC0 {
                if cur + 1 >= self.buf.len() {
                    return Err(WireError::InsufficientData);
                }
                let target = ((len as usize & 0x3F) << 8) | self.buf[cur + 1] as usize;
                if jump.is_none() {
                    jump = Some(cur);
                }
                if target >= self.buf.len() {
                    return Err(WireError::InsufficientData);
                }
                cur = target;
                continue;
            }
            if cur + 1 + len > self.buf.len() {
                return Err(WireError::InsufficientData);
            }
            let label = String::from_utf8_lossy(&self.buf[cur + 1..cur + 1 + len]).to_string();
            labels.segments.push((label.len(), label));
            cur += 1 + len;
        }
        let consumed = match jump {
            Some(j) => j + 2 - start,
            None => cur - start,
        };
        self.pos = match jump {
            Some(j) => j + 2,
            None => cur,
        };
        Ok((labels.to_string(), consumed))
    }

    /// Read a length-prefixed string; returns the bytes and the length used.
    pub fn read_string_total(&mut self) -> Result<(Vec<u8>, usize), WireError> {
        let len = self.read_u8()? as usize;
        let bytes = self.read_bytes(len)?;
        Ok((bytes, len + 1))
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Flags {
    pub response: bool,
    pub op_code: u8,
    pub authoritative: bool,
    pub truncated: bool,
    pub recursion_desired: bool,
    pub recursion_available: bool,
    pub authentic_data: bool,
