/// A complete DNS message.
#[derive(Clone, Debug)]
pub struct Message {
    pub txid: u16,
    pub flags: Flags,
    pub queries: Vec<Query>,
    pub answers: Vec<Record>,
    pub authorities: Vec<Record>,
    pub additionals: Vec<Record>,
}

#[derive(Clone, Debug)]
pub struct Query {
    pub name: String,
    pub num: u16,
    pub class: Class,
    pub r#type: RecordType,
}

impl Query {
    pub fn json(&self) -> String {
        let mut out = String::from("{\"name\":");
        out.push_str(&json_escape_wrapped(&self.name));
        out.push_str(",\"class\":");
        out.push_str(&json_escape_wrapped(&self.class.name()));
        out.push_str(",\"type\":");
        match self.r#type {
            RecordType::Other(OtherType::UnheardOf(n)) => out.push_str(&n.to_string()),
            ref t => out.push_str(&json_escape_wrapped(&t.name())),
        }
        out.push('}');
        out
    }
}

use crate::records::OtherType;

impl Message {
    /// Build a query packet exactly as dog does.
    #[allow(clippy::too_many_arguments)]
    pub fn build_query(
        txid: u16,
        labels: &Labels,
        r#type: &RecordType,
        class: &Class,
        edns: bool,
        udp_payload_size: u16,
        authoritative: bool,
        authentic: bool,
        checking_disabled: bool,
    ) -> Vec<u8> {
        let mut flags: u16 = 0x0100;
        if authoritative {
            flags |= 0x0400;
        }
        if authentic {
            flags |= 0x0020;
        }
        if checking_disabled {
            flags |= 0x0010;
        }
        let mut out = Vec::new();
        out.extend_from_slice(&txid.to_be_bytes());
        out.extend_from_slice(&flags.to_be_bytes());
        out.extend_from_slice(&1u16.to_be_bytes());
        out.extend_from_slice(&0u16.to_be_bytes());
        out.extend_from_slice(&0u16.to_be_bytes());
        out.extend_from_slice(&(if edns { 1u16 } else { 0u16 }).to_be_bytes());
        out.extend_from_slice(&crate::records::labels_bytes(labels));
        out.extend_from_slice(&r#type.number().to_be_bytes());
        out.extend_from_slice(&class.number().to_be_bytes());
        if edns {
            out.push(0);
            out.extend_from_slice(&41u16.to_be_bytes());
            out.extend_from_slice(&udp_payload_size.to_be_bytes());
            out.extend_from_slice(&0u32.to_be_bytes());
            out.extend_from_slice(&0u16.to_be_bytes());
        }
        out
    }

    /// Parse a response packet.
    pub fn parse(bytes: &[u8]) -> Result<Message, WireError> {
        let mut reader = Reader::new(bytes, 0);
        if reader.remaining() < 12 {
            return Err(WireError::InsufficientData);
        }
        let txid = reader.read_u16()?;
        let flags_raw = reader.read_u16()?;
        let qd = reader.read_u16()? as usize;
        let an = reader.read_u16()? as usize;
        let ns = reader.read_u16()? as usize;
        let ar = reader.read_u16()? as usize;
        let flags = Flags {
            response: flags_raw & 0x8000 != 0,
            op_code: ((flags_raw >> 11) & 0xF) as u8,
            authoritative: flags_raw & 0x0400 != 0,
            truncated: flags_raw & 0x0200 != 0,
            recursion_desired: flags_raw & 0x0100 != 0,
            recursion_available: flags_raw & 0x0080 != 0,
            authentic_data: flags_raw & 0x0020 != 0,
            checking_disabled: flags_raw & 0x0010 != 0,
            error_code: (flags_raw & 0xF) as u8,
        };
        let mut queries = Vec::new();
        for _ in 0..qd {
            let (name, _) = reader.read_name_total()?;
            let num = reader.read_u16()?;
            let cnum = reader.read_u16()?;
            let rtype = RecordType::from_number(num);
            queries.push(Query {
                name,
                num,
                class: Class::from_number(cnum),
                r#type,
            });
        }
        let mut answers = Vec::new();
        let mut authorities = Vec::new();
        let mut additionals = Vec::new();
        for (section, count) in [
            (Section::Answer, an),
            (Section::Authority, ns),
            (Section::Additional, ar),
        ] {
            for _ in 0..count {
                let (name, _) = reader.read_name_total()?;
                let num = reader.read_u16()?;
                let cnum = reader.read_u16()?;
                let ttl = reader.read_u32()?;
                let rdlen = reader.read_u16()? as usize;
                let data = if num == 41 {
                    parse_opt_data(&mut reader, ttl, rdlen, cnum)?
                } else {
                    parse_record_data(&mut reader, num, rdlen)?
                };
                let record = Record {
                    name,
                    num,
                    class: Class::from_number(cnum),
                    ttl,
                    data,
                    section,
                };
                match section {
                    Section::Answer => answers.push(record),
                    Section::Authority => authorities.push(record),
                    Section::Additional => additionals.push(record),
                }
            }
        }
        Ok(Message {
            txid,
            flags,
            queries,
            answers,
            authorities,
            additionals,
        })
    }
}
