            truncated: flags_raw & 0x0200 != 0,
            recursion_desired: flags_raw & 0x0100 != 0,
            recursion_available: flags_raw & 0x0080 != 0,
            authentic_data: flags_raw & 0x0020 != 0,
            checking_disabled: flags_raw & 0x0010 != 0,
            error_code: (flags_raw & 0xF) as u8,
        };
        let mut queries = Vec::new();
        for _ in 0..qd {
            let (name, _) = reader.read_name_total()?;
            let num = reader.read_u16()?;
            let cnum = reader.read_u16()?;
            let rtype = RecordType::from_number(num);
            queries.push(Query {
                name,
                num,
                class: Class::from_number(cnum),
                r#type,
            });
        }
        let mut answers = Vec::new();
        let mut authorities = Vec::new();
        let mut additionals = Vec::new();
        for (section, count) in [
            (Section::Answer, an),
            (Section::Authority, ns),
            (Section::Additional, ar),
        ] {
            for _ in 0..count {
                let (name, _) = reader.read_name_total()?;
                let num = reader.read_u16()?;
                let cnum = reader.read_u16()?;
                let ttl = reader.read_u32()?;
                let rdlen = reader.read_u16()? as usize;
                let data = if num == 41 {
                    parse_opt_data(&mut reader, ttl, rdlen, cnum)?
                } else {
                    parse_record_data(&mut reader, num, rdlen)?
                };
                let record = Record {
                    name,
                    num,
                    class: Class::from_number(cnum),
                    ttl,
                    data,
                    section,
                };
                match section {
                    Section::Answer => answers.push(record),
                    Section::Authority => authorities.push(record),
                    Section::Additional => additionals.push(record),
                }
            }
        }
        Ok(Message {
            txid,
            flags,
            queries,
            answers,
            authorities,
            additionals,
        })
    }
}
