//! DNS over TLS, using OpenSSL.

use std::io::Read;
use std::net::{SocketAddr, TcpStream};
use std::os::raw::{c_char, c_int, c_void};
use std::sync::Once;

use crate::tcp::TcpTransport;
use crate::ossl::{self, SSL, SSL_CTX};
use crate::{log, Error, Nameserver};

const DEFAULT_PORT: &str = "853";

extern "C" {
    fn SSL_connect(ssl: *mut SSL) -> c_int;
    fn SSL_write(ssl: *mut SSL, buf: *const c_void, num: c_int) -> c_int;
    fn SSL_read(ssl: *mut SSL, buf: *mut c_void, num: c_int) -> c_int;
    fn SSL_get_error(ssl: *mut SSL, ret: c_int) -> c_int;
    fn SSL_get_verify_result(ssl: *const SSL) -> std::os::raw::c_long;
    fn SSL_set_tlsext_host_name(ssl: *mut SSL, name: *const c_char) -> c_int;
    fn SSL_set1_host(ssl: *mut SSL, name: *const c_char) -> c_int;
    fn SSL_set1_ip(ssl: *mut SSL, ip: *const c_char) -> c_int;
}

static INIT: Once = Once::new();

pub struct TlsTransport {
    ssl: *mut SSL,
    stream: TcpStream,
    addr: SocketAddr,
}

impl TlsTransport {
    pub fn new(ns: &Nameserver) -> Result<Self, Error> {
        let (host, port) = parse_nameserver(&ns.address);
        log::info("dns_transport::tls", "Opening TLS socket");
        let addr = resolve(&host, port)?;
        log::info(
            "dns_transport::tls",
            &format!("Connecting using domain {:?}", host),
        );
        let stream = TcpStream::connect(addr).map_err(Error::Io)?;
        INIT.call_once(|| ossl::init());
        let ctx = Context::client()?;
        let ssl = ctx.new_session(&stream, &host)?;
        log::debug("dns_transport::tls", "Connected");
        Ok(TlsTransport { ssl, stream, addr })
    }

    pub fn send(&mut self, bytes: &[u8]) -> Result<(), Error> {
        log::info(
            "dns_transport::tls",
            &format!(
                "Sending {} bytes of data to {} over TLS",
                bytes.len(),
                self.addr
            ),
        );
        let mut framed = Vec::with_capacity(bytes.len() + 2);
        framed.extend_from_slice(&(bytes.len() as u16).to_be_bytes());
        framed.extend_from_slice(bytes);
        let ret = unsafe {
            SSL_write(self.ssl, framed.as_ptr() as *const c_void, framed.len() as c_int)
        };
        if ret <= 0 {
            return Err(Error::Tls(tls_error(self.ssl, ret)));
        }
        log::debug("dns_transport::tls", "Wrote all bytes");
        Ok(())
    }

    pub fn receive(&mut self) -> Result<Vec<u8>, Error> {
        log::info("dns_transport::tcp", "Waiting to receive...");
        let mut header = [0u8; 2];
        read_ssl(self.ssl, &mut header)?;
        let len = u16::from_be_bytes(header) as usize;
        let mut buffer = vec![0u8; len];
        let mut pos = 0usize;
        while pos < len {
            let n = ssl_read(self.ssl, &mut buffer[pos..])?;
            pos += n;
        }
        log::info("dns_transport::tcp", &format!("Received {} bytes of data", pos + 2));
        log::debug("dns_transport::tcp", "We have enough bytes");
        Ok(buffer)
    }
}

/// Wrap a TCP stream in TLS, verifying the certificate.
fn tls_connect(ssl: *mut SSL) -> Result<(), Error> {
    let ret = unsafe { SSL_connect(ssl) };
    if ret <= 0 {
        Err(Error::Tls(tls_error(ssl, ret)))
    } else {
        Ok(())
    }
}

fn ssl_read(ssl: *mut SSL, buf: &mut [u8]) -> Result<usize, Error> {
    let ret = unsafe { SSL_read(ssl, buf.as_mut_ptr() as *mut c_void, buf.len() as c_int) };
    if ret > 0 {
        return Ok(ret as usize);
    }
    Err(Error::Tls(tls_error(ssl, ret)))
}

fn read_ssl(ssl: *mut SSL, buf: &mut [u8]) -> Result<(), Error> {
    let mut got = 0usize;
    while got < buf.len() {
        let n = ssl_read(ssl, &mut buf[got..])?;
        if n == 0 {
            return Err(Error::TruncatedResponse);
        }
        got += n;
    }
    Ok(())
}

fn tls_error(ssl: *mut SSL, ret: c_int) -> String {
    let error = unsafe { SSL_get_error(ssl, ret) };
    if error == ossl::SSL_ERROR_SYSCALL {
        return "unexpected EOF".to_string();
    }
    let verify = unsafe { SSL_get_verify_result(ssl) };
    if verify != ossl::X509_V_OK {
        return format!(
            "error:1416F086:SSL routines:tls_process_server_certificate:certificate verify failed:ssl/statem/statem_clnt.c:1913:{}",
            ossl::describe_verify_result(verify)
        );
    }
    match ossl::tls_error_string() {
        Some(s) => s,
        None => "unknown TLS error".to_string(),
    }
}

struct Context {
    ctx: *mut SSL_CTX,
}

impl Context {
    fn client() -> Result<Self, Error> {
        let ctx = ossl::new_client_context();
        if ctx.is_null() {
            return Err(Error::Tls("could not create TLS context".to_string()));
        }
        ossl::configure_verify(ctx);
        Ok(Context { ctx })
    }

    fn new_session(&self, stream: &TcpStream, host: &str) -> Result<*mut SSL, Error> {
        let ssl = ossl::new_session(self.ctx);
        if ssl.is_null() {
            return Err(Error::Tls("could not create TLS session".to_string()));
        }
        ossl::set_fd(ssl, stream);
        let cstr = std::ffi::CString::new(host.to_string()).unwrap();
        unsafe {
            SSL_set_tlsext_host_name(ssl, cstr.as_ptr());
            if host.parse::<std::net::IpAddr>().is_ok() {
                SSL_set1_ip(ssl, cstr.as_ptr());
            } else {
                SSL_set1_host(ssl, cstr.as_ptr());
            }
        }
        tls_connect(ssl)?;
        Ok(ssl)
    }
}

/// Split a TLS nameserver into its host and port parts.
fn parse_nameserver(ns: &str) -> (String, u16) {
    let mut parts = ns.split(':');
    let host = parts.next().unwrap_or("").to_string();
    let port = parts.next().unwrap_or(DEFAULT_PORT).parse::<u16>().unwrap_or_else(|e| panic!("Invalid port number: {:?}", e));
    (host, port)
}

fn resolve(host: &str, port: u16) -> Result<SocketAddr, Error> {
    use std::net::ToSocketAddrs;
    let candidates: Vec<SocketAddr> = (host, port)
        .to_socket_addrs()
        .map_err(Error::Io)?
        .collect();
    candidates
        .into_iter()
        .next()
        .ok_or_else(|| Error::Io(std::io::Error::new(std::io::ErrorKind::InvalidInput, "no address")))
}
