part2 = '''
fn connect(stream: &TcpStream, host: &str) -> Result<*mut SSL, Error> {
    let ctx = ossl::client_context()?;
    let ssl = ossl::new_session(ctx);
    if ssl.is_null() {
        ossl::free_context(ctx);
        return Err(Error::Tls("could not create TLS session".to_string()));
    }
    ossl::set_fd(ssl, stream);
    let cstr = std::ffi::CString::new(host.to_string()).unwrap();
    unsafe {
        SSL_set_tlsext_host_name(ssl, cstr.as_ptr());
        if host.parse::<std::net::IpAddr>().is_ok() {
            SSL_set1_ip(ssl, cstr.as_ptr());
        } else {
            SSL_set1_host(ssl, cstr.as_ptr());
        }
    }
    let ret = unsafe { SSL_connect(ssl) };
    if ret <= 0 {
        ossl::free_session(ssl);
        ossl::free_context(ctx);
        return Err(Error::Tls(tls_error(ssl, ret)));
    }
    Ok(ssl)
}

fn ssl_read(ssl: *mut SSL) -> Result<Vec<u8>, Error> {
    let mut buf = [0u8; 4096];
    let ret = unsafe { SSL_read(ssl, buf.as_mut_ptr() as *mut c_void, buf.len() as c_int) };
    if ret > 0 {
        return Ok(buf[..ret as usize].to_vec());
    }
    if ret == 0 {
        return Ok(Vec::new());
    }
    Err(Error::Tls(tls_error(ssl, ret)))
}

/// dog's rendering of an OpenSSL failure.
fn tls_error(ssl: *mut SSL, ret: c_int) -> String {
    let error = unsafe { SSL_get_error(ssl, ret) };
    if error == ossl::SSL_ERROR_SYSCALL {
        return "unexpected EOF".to_string();
    }
    let verify = unsafe { SSL_get_verify_result(ssl) };
    if verify != ossl::X509_V_OK {
        return format!(
            "error:1416F086:SSL routines:tls_process_server_certificate:certificate verify failed:ssl/statem/statem_clnt.c:1913:{}",
            ossl::describe_verify_result(verify)
        );
    }
    match ossl::tls_error_string() {
        Some(s) => s,
        None => "unknown TLS error".to_string(),
    }
}

/// HTTPS always connects to port 443, the standard HTTPS port.
fn resolve(host: &str) -> Result<SocketAddr, Error> {
    use std::net::ToSocketAddrs;
    let candidates: Vec<SocketAddr> = (host, 443).to_socket_addrs().map_err(Error::Io)?.collect();
    candidates
        .into_iter()
        .next()
        .ok_or_else(|| Error::Io(std::io::Error::new(std::io::ErrorKind::InvalidInput, "no address")))
}
