//!
//! dog sends the DNS message as the body of an HTTP POST request, and reads
//! the DNS message back out of the response body. The nameserver must be a
//! whole URL, complete with scheme and path, because dog needs somewhere to
//! post the message to.

use std::net::{SocketAddr, TcpStream};
use std::os::raw::{c_char, c_int, c_void};
use std::sync::Once;

use crate::ossl::{self, SSL};
use crate::{log, Error};

extern "C" {
    fn SSL_connect(ssl: *mut SSL) -> c_int;
    fn SSL_write(ssl: *mut SSL, buf: *const c_void, num: c_int) -> c_int;
    fn SSL_read(ssl: *mut SSL, buf: *mut c_void, num: c_int) -> c_int;
    fn SSL_get_error(ssl: *mut SSL, ret: c_int) -> c_int;
    fn SSL_get_verify_result(ssl: *const SSL) -> std::os::raw::c_long;
    fn SSL_set_tlsext_host_name(ssl: *mut SSL, name: *const c_char) -> c_int;
    fn SSL_set1_host(ssl: *mut SSL, name: *const c_char) -> c_int;
    fn SSL_set1_ip(ssl: *mut SSL, ip: *const c_char) -> c_int;
}

static INIT: Once = Once::new();

/// An HTTPS transport: a TLS session with an HTTP request layered on top.
pub struct HttpTransport {
    ssl: *mut SSL,
    url: String,
    host: String,
    path: String,
}

impl HttpTransport {
    /// Open an HTTPS session to the given URL.
    pub fn new(ns: &str) -> Result<Self, Error> {
        let (host, path) = parse_url(ns).unwrap_or_else(|| panic!("Invalid HTTPS nameserver"));
        let url = ns.to_string();
        let addr = resolve(&host)?;
        log::info(
            "dns_transport::https",
            &format!("Opening TLS socket to {:?}", host),
        );
        let stream = TcpStream::connect(addr).map_err(Error::Io)?;
        INIT.call_once(|| ossl::init());
        let ssl = connect(&stream, &host)?;
        log::debug("dns_transport::https", "Connected");
        Ok(HttpTransport { ssl, url, host, path })
    }

    /// Send the DNS message as the body of an HTTP POST request.
    pub fn send(&mut self, bytes: &[u8]) -> Result<(), Error> {
        let mut request = Vec::new();
        request.extend_from_slice(b"POST ");
        request.extend_from_slice(self.path.as_bytes());
        request.extend_from_slice(b" HTTP/1.1\\r\\n");
        request.extend_from_slice(b"Host: ");
        request.extend_from_slice(self.host.as_bytes());
        request.extend_from_slice(b"\\r\\n");
        request.extend_from_slice(b"Content-Type: application/dns-message\\r\\n");
        request.extend_from_slice(b"Accept: application/dns-message\\r\\n");
        request.extend_from_slice(b"User-Agent: dog/0.2.0-pre\\r\\n");
        request.extend_from_slice(
            format!("Content-Length: {}\\r\\n", bytes.len()).as_bytes(),
        );
        request.extend_from_slice(b"\\r\\n");
        request.extend_from_slice(bytes);
        log::info(
            "dns_transport::https",
            &format!(
                "Sending {} bytes of data to {:?} over HTTPS",
                request.len(),
                self.url
            ),
        );
        let ret = unsafe {
            SSL_write(self.ssl, request.as_ptr() as *const c_void, request.len() as c_int)
        };
        if ret <= 0 {
            return Err(Error::Tls(tls_error(self.ssl, ret)));
        }
        log::debug("dns_transport::https", "Wrote all bytes");
        Ok(())
    }

    /// Read the HTTP response, and pull the DNS message out of its body.
    pub fn receive(&mut self) -> Result<Vec<u8>, Error> {
        log::info("dns_transport::https", "Waiting to receive...");
        let mut buffer: Vec<u8> = Vec::new();
        let mut content_length: Option<usize> = None;
        loop {
            let chunk = ssl_read(self.ssl)?;
            buffer.extend_from_slice(&chunk);
            log::info(
                "dns_transport::https",
                &format!("Received {} bytes of data", chunk.len()),
            );
            if let Some(index) = find_header_end(&buffer) {
                let headers = String::from_utf8_lossy(&buffer[..index]);
                let mut body_start = index + 4;
                for line in headers.split("\\r\\n").skip(1) {
                    if let Some(colon) = line.find(':') {
                        let name = line[..colon].trim().to_string();
                        let value = line[colon + 1..].trim().to_string();
                        log::debug(
                            "dns_transport::https",
                            &format!("Header {:?} -> {:?}", name, value),
                        );
                        if name.eq_ignore_ascii_case("content-length") {
                            if let Ok(n) = value.parse::<usize>() {
                                content_length = Some(n);
                            }
                        }
                    }
                }
                let mut body = buffer[body_start..].to_vec();
                loop {
                    match content_length {
                        Some(want) if body.len() >= want => break,
                        Some(_) => {
                            let chunk = ssl_read(self.ssl)?;
                            if chunk.is_empty() {
