                            }
                            body.extend_from_slice(&chunk);
                            log::info(
                                "dns_transport::https",
                                &format!("Received {} bytes of data", chunk.len()),
                            );
                        }
                        None => break,
                    }
                }
                log::debug(
                    "dns_transport::https",
                    &format!("HTTP body has {} bytes", body.len()),
                );
                return Ok(body);
            }
        }
    }
}

