pub mod tcp;
pub mod tls;
pub mod udp;
pub mod ossl;

pub use dns::log;

/// An error dog ran into while talking to a nameserver.
#[derive(Debug)]
pub enum Error {
    /// Something went wrong on the network.
    Io(std::io::Error),
    /// The TLS handshake, or the TLS layer itself, failed.
    Tls(String),
    /// The response was cut short.
    TruncatedResponse,
}

impl Error {
    /// The phase dog reports the error in.
    pub fn phase(&self) -> &'static str {
        match self {
            Error::Io(_) => "network",
            Error::Tls(_) => "tls",
            Error::TruncatedResponse => "network",
        }
    }

    pub fn message(&self) -> String {
        match self {
            Error::Io(e) => e.to_string(),
            Error::Tls(s) => s.clone(),
            Error::TruncatedResponse => "Truncated response".to_string(),
        }
    }
}

/// The transport dog should use to talk to a nameserver.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum TransportType {
    Automatic,
    UDP,
    TCP,
    TLS,
    HTTPS,
}

impl TransportType {
    pub fn debug(&self) -> String {
        match self {
            TransportType::Automatic => "Automatic".to_string(),
            TransportType::UDP => "UDP".to_string(),
            TransportType::TCP => "TCP".to_string(),
            TransportType::TLS => "TLS".to_string(),
            TransportType::HTTPS => "HTTPS".to_string(),
        }
    }
}
