{"command": "cat > dns/src/log.rs <<'EOF'
//! dog's logger: writes coloured diagnostics to standard error.

use std::sync::atomic::{AtomicU8, Ordering};

static LEVEL: AtomicU8 = AtomicU8::new(0);

pub const OFF: u8 = 0;
pub const DEBUG: u8 = 1;
pub const TRACE: u8 = 2;

/// Look at the `DOG_DEBUG` environment variable and set the log level.
pub fn setup() {
    let level = match std::env::var("DOG_DEBUG") {
        Ok(value) if !value.is_empty() => {
            if value == "trace" {
                TRACE
            } else {
                DEBUG
            }
        }
        _ => OFF,
    };
    LEVEL.store(level, Ordering::Relaxed);
}

pub fn level() -> u8 {
    LEVEL.load(Ordering::Relaxed)
}

fn bracket(text: &str) -> String {
    format!("\x1b[38;5;243m{}\x1b[0m", text)
}

fn colourise(level: &str) -> String {
    let colour = match level {
        "TRACE" => "38;5;245",
        "DEBUG" => "34",
        "INFO" => "36",
        "WARN" => "33",
        _ => "31",
    };
    format!("\x1b[{}m{}\x1b[0m", colour, level)
}

fn emit(level: &str, target: &str, message: &str) {
    eprintln!(
        "{}{} {}{} {}",
        bracket("["),
        colourise(level),
        target,
        bracket("]"),
        message
    );
}

pub fn trace(target: &str, message: &str) {
    if level() >= TRACE {
        emit("TRACE", target, message);
    }
}

pub fn debug(target: &str, message: &str) {
    if level() >= DEBUG {
        emit("DEBUG", target, message);
    }
}

pub fn info(target: &str, message: &str) {
    if level() >= DEBUG {
        emit("INFO", target, message);
    }
}

pub fn warn(target: &str, message: &str) {
    if level() >= DEBUG {
        emit("WARN", target, message);
    }
}

pub fn error(target: &str, message: &str) {
    if level() >= DEBUG {
        emit("ERROR", target, message);
    }
}
