//! dog's command-line options.

use dns::log;
use dns::records::{OtherType, RecordType};
use dns::Class;
use dns_transport::TransportType;
use std::io::Write;

/// What to colour the output with.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ColourSetting {
    Always,
    Automatic,
    Never,
}

impl ColourSetting {
    pub fn debug(&self) -> String {
        match self {
            ColourSetting::Always => "Always".to_string(),
            ColourSetting::Automatic => "Automatic".to_string(),
            ColourSetting::Never => "Never".to_string(),
        }
    }

    pub fn parse(text: &str) -> Option<Self> {
        match text.to_ascii_lowercase().as_str() {
            "always" => Some(ColourSetting::Always),
            "automatic" => Some(ColourSetting::Automatic),
            "never" => Some(ColourSetting::Never),
            _ => None,
        }
    }
}

/// How dog's text output is formatted.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct TextFormat {
    pub format_durations: bool,
}

/// How dog's output is rendered.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Format {
    Text(ColourSetting, TextFormat),
    JSON,
    Short(TextFormat),
}

/// Whether dog opts in to EDNS.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Edns {
    Disable,
    SendAndHide,
    SendAndShow,
}

/// Uncommon protocol-level tweaks.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct ProtocolTweaks {
    pub set_authoritative_flag: bool,
    pub set_authentic_flag: bool,
    pub set_checking_disabled_flag: bool,
    pub udp_payload_size: Option<u16>,
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub enum ResolverType {
    SystemDefault,
    Specific(String),
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub enum TxidGenerator {
    Random,
    Sequence(u16),
}

/// The inputs dog takes from the command line.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Inputs {
    pub domains: Vec<dns::name::Labels>,
    pub record_types: Vec<RecordType>,
    pub classes: Vec<Class>,
    pub resolver_types: Vec<ResolverType>,
    pub transport_types: Vec<TransportType>,
}

/// Everything dog needs to know to do its job.
pub struct Options {
    pub inputs: Inputs,
    pub txid_generator: TxidGenerator,
    pub edns: Edns,
    pub protocol_tweaks: ProtocolTweaks,
    pub measure_time: bool,
    pub format: Format,
}

impl Options {
    /// Render the way dog's `Debug` implementation would.
    pub fn debug_string(&self) -> String {
        let mut out = String::new();
        out.push_str("Options {\n");
        out.push_str("    requests: RequestGenerator {\n");
        out.push_str("        inputs: Inputs {\n");
        out.push_str("            domains: [\n");
        for domain in &self.inputs.domains {
            out.push_str("                Labels {\n");
            out.push_str("                    segments: [\n");
            for (len, seg) in &domain.segments {
                out.push_str("                        (\n");
                out.push_str(&format!("                            {},\n", len));
                out.push_str(&format!("                            {:?},\n", seg));
                out.push_str("                        ),\n");
            }
            out.push_str("                    ],\n");
            out.push_str("                },\n");
        }
        out.push_str("            ],\n");
        out.push_str("            record_types: [\n");
        for t in &self.inputs.record_types {
            out.push_str("                ");
            out.push_str(&t.debug());
            out.push_str(",\n");
        }
        out.push_str("            ],\n");
        out.push_str("            classes: [\n");
        for c in &self.inputs.classes {
            out.push_str("                ");
            out.push_str(&c.debug());
            out.push_str(",\n");
        }
        out.push_str("            ],\n");
        out.push_str("            resolver_types: [\n");
        for r in &self.inputs.resolver_types {
            match r {
                ResolverType::SystemDefault => {
                    out.push_str("                SystemDefault,\n");
                }
                ResolverType::Specific(addr) => {
                    out.push_str("                Specific(\n");
                    out.push_str(&format!("                    {:?},\n", addr));
                    out.push_str("                ),\n");
                }
            }
        }
        out.push_str("            ],\n");
        out.push_str("            transport_types: [\n");
        for t in &self.inputs.transport_types {
            out.push_str("                ");
            out.push_str(&t.debug());
            out.push_str(",\n");
        }
        out.push_str("            ],\n");
        out.push_str("        },\n");
        match &self.txid_generator {
            TxidGenerator::Random => out.push_str("        txid_generator: Random,\n"),
            TxidGenerator::Sequence(n) => out.push_str(&format!(
                "        txid_generator: Sequence(\n            {},\n        ),\n",
                n
            )),
        }
        match &self.edns {
            Edns::Disable => out.push_str("        edns: Disable,\n"),
            Edns::SendAndHide => out.push_str("        edns: SendAndHide,\n"),
            Edns::SendAndShow => out.push_str("        edns: SendAndShow,\n"),
        }
        out.push_str("        protocol_tweaks: ProtocolTweaks {\n");
        out.push_str(&format!(
            "            set_authoritative_flag: {},\n",
            self.protocol_tweaks.set_authoritative_flag
        ));
        out.push_str(&format!(
            "            set_authentic_flag: {},\n",
            self.protocol_tweaks.set_authentic_flag
        ));
        out.push_str(&format!(
            "            set_checking_disabled_flag: {},\n",
            self.protocol_tweaks.set_checking_disabled_flag
        ));
        match self.protocol_tweaks.udp_payload_size {
            None => out.push_str("            udp_payload_size: None,\n"),
            Some(n) => out.push_str(&format!(
                "            udp_payload_size: Some(\n                {},\n            ),\n",
                n
            )),
        }
        out.push_str("        },\n");
        out.push_str("    },\n");
        out.push_str(&format!("    measure_time: {},\n", self.measure_time));
        match &self.format {
            Format::Text(colour, text_format) => {
                out.push_str("    format: Text(\n");
                out.push_str(&format!(
                    "        {},\n",
                    colour.debug()
                ));
                out.push_str("        TextFormat {\n");
                out.push_str(&format!(
                    "            format_durations: {},\n",
                    text_format.format_durations
                ));
                out.push_str("        },\n");
                out.push_str("    ),\n");
            }
            Format::JSON => out.push_str("    format: JSON,\n"),
            Format::Short(text_format) => {
                out.push_str("    format: Short(\n");
                out.push_str("        TextFormat {\n");
                out.push_str(&format!(
                    "            format_durations: {},\n",
                    text_format.format_durations
                ));
                out.push_str("        },\n");
                out.push_str("    ),\n");
            }
        }
        out.push('}');
        out
    }
}

/// The result of parsing the command line, before dog looks anything up.
pub enum Parsed {
    Version,
    Help,
    Run(Box<Options>),
    /// dog needs no arguments at all: it prints its help and complains.
    NoDomains,
}

/// An error dog found in its command-line arguments.
pub struct OptionError(pub String);

fn is_repeatable(long: &str) -> bool {
    matches!(long, "query" | "type" | "nameserver" | "class" | "tweaks")
}

/// Parse dog's command-line arguments.
pub fn parse(args: &[String]) -> Result<Parsed, OptionError> {
    let mut domains: Vec<dns::name::Labels> = Vec::new();
    let mut record_types: Vec<RecordType> = Vec::new();
    let mut classes: Vec<Class> = Vec::new();
    let mut resolver_types: Vec<ResolverType> = Vec::new();
    let mut transport_types: Vec<TransportType> = Vec::new();
    let mut txid_generator = TxidGenerator::Random;
    let mut edns = Edns::SendAndHide;
    let mut tweaks = ProtocolTweaks {
        set_authoritative_flag: false,
        set_authentic_flag: false,
        set_checking_disabled_flag: false,
        udp_payload_size: None,
    };
    let mut measure_time = false;
    let mut format: Option<Format> = None;
    let mut seen: Vec<&str> = Vec::new();
    let mut help = false;
    let mut version = false;
    let mut transport_given = false;
    let mut end_of_options = false;

    let mut push_transport = |name: &'static str, kind: TransportType, seen: &mut Vec<&'static str>| -> Result<(), OptionError> {
        if seen.contains(&name) {
            return Err(OptionError(format!("Option '{}' given more than once", name)));
        }
        seen.push(name);
        transport_types.push(kind);
        transport_given = true;
        Ok(())
    };

    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if !end_of_options && arg == "--" {
            end_of_options = true;
            i += 1;
            continue;
        }
        if !end_of_options && arg.starts_with("--") {
            let body = &arg[2..];
            let (name, value) = match body.find('=') {
                Some(idx) => (&body[..idx], Some(body[idx + 1..].to_string())),
                None => (body, None),
            };
            match name {
                "query" => {
                    let value = take_value(&mut i, args, value, "query")?;
                    push_domain(&value, &mut domains)?;
                }
                "type" => {
                    let value = take_value(&mut i, args, value, "type")?;
                    push_type(&value, &mut record_types)?;
                }
                "nameserver" => {
                    let value = take_value(&mut i, args, value, "nameserver")?;
                    log::trace("dog::options", &format!("Got nameserver -> {:?}", value));
                    resolver_types.push(ResolverType::Specific(value));
                }
                "class" => {
                    let value = take_value(&mut i, args, value, "class")?;
                    push_class(&value, &mut classes)?;
                }
                "edns" => {
                    if seen.contains(&"edns") {
                        return Err(OptionError("Option 'edns' given more than once".to_string()));
                    }
                    seen.push("edns");
                    let value = take_value(&mut i, args, value, "edns")?;
                    edns = match value.as_str() {
                        "disable" => Edns::Disable,
                        "hide" => Edns::SendAndHide,
                        "show" => Edns::SendAndShow,
                        _ => {
                            return Err(OptionError(format!(
                                "Invalid EDNS setting {:?}",
                                value
                            )))
                        }
                    };
                }
                "txid" => {
                    if seen.contains(&"txid") {
                        return Err(OptionError("Option 'txid' given more than once".to_string()));
                    }
                    seen.push("txid");
                    let value = take_value(&mut i, args, value, "txid")?;
                    let num = match value.parse::<u16>() {
                        Ok(n) => n,
                        Err(_) => {
                            return Err(OptionError(format!(
                                "Invalid transaction ID {:?}",
                                value
                            )))
                        }
                    };
                    txid_generator = TxidGenerator::Sequence(num);
                }
                "udp" => {
                    if value.is_some() {
                        return Err(OptionError(
                            "Option 'udp' does not take an argument".to_string(),
                        ));
                    }
                    push_transport("udp", TransportType::UDP, &mut seen)?;
                }
                "tcp" => {
                    if value.is_some() {
                        return Err(OptionError(
                            "Option 'tcp' does not take an argument".to_string(),
                        ));
                    }
                    push_transport("tcp", TransportType::TCP, &mut seen)?;
                }
                "tls" => {
                    if value.is_some() {
                        return Err(OptionError(
                            "Option 'tls' does not take an argument".to_string(),
                        ));
                    }
                    push_transport("tls", TransportType::TLS, &mut seen)?;
                }
                "https" => {
                    if value.is_some() {
                        return Err(OptionError(
                            "Option 'https' does not take an argument".to_string(),
                        ));
                    }
                    push_transport("https", TransportType::HTTPS, &mut seen)?;
                }
                "short" => {
                    if value.is_some() {
                        return Err(OptionError(
                            "Option 'short' does not take an argument".to_string(),
                        ));
                    }
                    if seen.contains(&"short") {
                        return Err(OptionError("Option 'short' given more than once".to_string()));
                    }
                    seen.push("short");
                    format = Some(Format::Short(TextFormat { format_durations: true }));
                }
                "json" => {
                    if value.is_some() {
                        return Err(OptionError(
                            "Option 'json' does not take an argument".to_string(),
                        ));
                    }
                    if seen.contains(&"json") {
                        return Err(OptionError("Option 'json' given more than once".to_string()));
                    }
                    seen.push("json");
                    format = Some(Format::JSON);
                }
                "color" | "colour" => {
                    if seen.contains(&"color") {
                        return Err(OptionError("Option 'color' given more than once".to_string()));
                    }
                    seen.push("color");
                    let value = take_value(&mut i, args, value, name)?;
                    let colour = match ColourSetting::parse(&value) {
                        Some(c) => c,
                        None => {
                            return Err(OptionError(format!(
                                "Invalid colour setting {:?}",
                                value
                            )))
                        }
                    };
                    let durations = match &format {
                        Some(Format::Text(_, t)) | Some(Format::Short(t)) => t.format_durations,
                        _ => true,
                    };
                    format = Some(Format::Text(colour, TextFormat { format_durations: durations }));
                }
                "seconds" => {
                    if value.is_some() {
                        return Err(OptionError(
                            "Option 'seconds' does not take an argument".to_string(),
                        ));
                    }
                    if seen.contains(&"seconds") {
                        return Err(OptionError(
                            "Option 'seconds' given more than once".to_string(),
                        ));
                    }
                    seen.push("seconds");
                    match &mut format {
                        Some(Format::Text(c, t)) => {
                            *t = TextFormat { format_durations: false };
                            let _ = c;
                        }
                        Some(Format::Short(t)) => *t = TextFormat { format_durations: false },
                        _ => format = Some(Format::Text(ColourSetting::Automatic, TextFormat { format_durations: false })),
                    }
                    let durations = false;
                    let _ = durations;
                    set_durations(&mut format, false);
                }
                "time" => {
                    if value.is_some() {
                        return Err(OptionError(
                            "Option 'time' does not take an argument".to_string(),
                        ));
                    }
                    if seen.contains(&"time") {
                        return Err(OptionError("Option 'time' given more than once".to_string()));
                    }
                    seen.push("time");
                    measure_time = true;
                }
                "help" => {
                    if value.is_some() {
                        return Err(OptionError(
                            "Option 'help' does not take an argument".to_string(),
                        ));
                    }
                    if seen.contains(&"help") {
                        return Err(OptionError("Option 'help' given more than once".to_string()));
                    }
                    seen.push("help");
                    help = true;
                }
                "version" => {
                    if value.is_some() {
                        return Err(OptionError(
                            "Option 'version' does not take an argument".to_string(),
                        ));
                    }
                    if seen.contains(&"version") {
                        return Err(OptionError(
                            "Option 'version' given more than once".to_string(),
                        ));
                    }
                    seen.push("version");
                    version = true;
                }
                _ => {
                    return Err(OptionError(format!(
                        "Unrecognized option: '{}'",
                        name
                    )))
                }
            }
            i += 1;
            continue;
        }
        if !end_of_options && arg.len() > 1 && arg.starts_with('-') {
            let chars: Vec<char> = arg.chars().collect();
            let mut j = 1usize;
            while j < chars.len() {
                let c = chars[j];
                j += 1;
                match c {
                    'q' => {
                        let value = short_value(&chars, &mut j, &mut i, args, "query")?;
                        push_domain(&value, &mut domains)?;
                    }
                    't' => {
                        let value = short_value(&chars, &mut j, &mut i, args, "type")?;
                        push_type(&value, &mut record_types)?;
                    }
                    'n' => {
                        let value = short_value(&chars, &mut j, &mut i, args, "nameserver")?;
                        log::trace("dog::options", &format!("Got nameserver -> {:?}", value));
                        resolver_types.push(ResolverType::Specific(value));
                    }
                    'Z' => {
                        let value = short_value(&chars, &mut j, &mut i, args, "tweaks")?;
                        apply_tweak(&value, &mut tweaks)?;
                    }
                    'U' => push_transport("udp", TransportType::UDP, &mut seen)?,
                    'T' => push_transport("tcp", TransportType::TCP, &mut seen)?,
                    'S' => push_transport("tls", TransportType::TLS, &mut seen)?,
                    'H' => push_transport("https", TransportType::HTTPS, &mut seen)?,
                    '1' => {
                        if seen.contains(&"short") {
                            return Err(OptionError(
                                "Option 'short' given more than once".to_string(),
                            ));
                        }
                        seen.push("short");
                        format = Some(Format::Short(TextFormat { format_durations: true }));
                    }
                    'J' => {
                        if seen.contains(&"json") {
                            return Err(OptionError(
                                "Option 'json' given more than once".to_string(),
                            ));
                        }
                        seen.push("json");
                        format = Some(Format::JSON);
                    }
                    'v' => {
                        if seen.contains(&"version") {
                            return Err(OptionError(
                                "Option 'version' given more than once".to_string(),
                            ));
                        }
                        seen.push("version");
                        version = true;
                    }
                    '?' => {
                        if seen.contains(&"help") {
                            return Err(OptionError(
                                "Option 'help' given more than once".to_string(),
                            ));
                        }
                        seen.push("help");
                        help = true;
                    }
                    other => {
                        return Err(OptionError(format!(
                            "Unrecognized option: '{}'",
                            other
                        )))
                    }
                }
            }
            i += 1;
            continue;
        }
        interpret_argument(arg, &mut domains, &mut record_types, &mut classes)?;
        i += 1;
    }

    if !transport_given {
        transport_types.push(TransportType::Automatic);
    }
    if classes.is_empty() {
        classes.push(Class::Internet);
    }
    if record_types.is_empty() {
        record_types.push(RecordType::A);
    }

    if help {
        return Ok(Parsed::Help);
    }
    if version {
        return Ok(Parsed::Version);
    }
    if domains.is_empty() {
        return Ok(Parsed::NoDomains);
    }
    Ok(Parsed::Run(Box::new(Options {
        inputs: Inputs {
            domains,
            record_types,
            classes,
            resolver_types,
            transport_types,
        },
        txid_generator,
        edns,
        protocol_tweaks: tweaks,
        measure_time,
        format: format.unwrap_or(Format::Text(
            ColourSetting::Automatic,
            TextFormat { format_durations: true },
        )),
    })))
}

fn set_durations(format: &mut Option<Format>, durations: bool) {
    match format {
        Some(Format::Text(_, t)) => t.format_durations = durations,
        Some(Format::Short(t)) => t.format_durations = durations,
        other => {
            *other = Some(Format::Text(
                ColourSetting::Automatic,
                TextFormat { format_durations: durations },
            ))
        }
    }
}

fn take_value(
    i: &mut usize,
    args: &[String],
    value: Option<String>,
    name: &str,
) -> Result<String, OptionError> {
    if let Some(v) = value {
        return Ok(v);
    }
    if *i + 1 < args.len() {
        *i += 1;
        return Ok(args[*i].clone());
    }
    Err(OptionError(format!(
        "Argument to option '{}' missing",
        name
    )))
}

fn short_value(
    chars: &[char],
    j: &mut usize,
    i: &mut usize,
    args: &[String],
    name: &str,
) -> Result<String, OptionError> {
    if *j < chars.len() {
        let value: String = chars[*j..].iter().collect();
        *j = chars.len();
        return Ok(value);
    }
    if *i + 1 < args.len() {
        *i += 1;
        return Ok(args[*i].clone());
    }
    Err(OptionError(format!(
        "Argument to option '{}' missing",
        name
    )))
}

fn push_domain(value: &str, domains: &mut Vec<dns::name::Labels>) -> Result<(), OptionError> {
    match dns::name::Labels::parse(value) {
        Ok(labels) => {
            log::trace("dog::options", &format!("Got domain -> {:?}", value));
            domains.push(labels);
            Ok(())
        }
        Err(()) => Err(OptionError(format!("Invalid domain {:?}", value))),
    }
}

fn push_type(value: &str, types: &mut Vec<RecordType>) -> Result<(), OptionError> {
    match RecordType::parse(value) {
        Ok(Some(t)) => {
            log::trace("dog::options", &format!("Got qtype -> {:?}", value));
            types.push(t);
            Ok(())
        }
        Ok(None) => Err(OptionError(format!("Invalid query type {:?}", value))),
        Err(()) => Err(OptionError(
            "OPT request is sent by default (see -Z flag)".to_string(),
        )),
    }
}

fn push_class(value: &str, classes: &mut Vec<Class>) -> Result<(), OptionError> {
    let class = match value.to_ascii_lowercase().as_str() {
        "in" => Class::Internet,
        "ch" => Class::Chaos,
        "hs" => Class::Hesiod,
        _ => return Err(OptionError(format!("Invalid query class {:?}", value))),
    };
    log::trace("dog::options", &format!("Got qclass -> {:?}", value));
    classes.push(class);
    Ok(())
}

fn apply_tweak(value: &str, tweaks: &mut ProtocolTweaks) -> Result<(), OptionError> {
    let mut set = false;
    for tweak in value.split(',') {
        if tweak.is_empty() {
            continue;
        }
        set = true;
        if let Some(rest) = tweak.strip_prefix("bufsize=") {
            match rest.parse::<u16>() {
                Ok(n) => tweaks.udp_payload_size = Some(n),
                Err(_) => return Err(OptionError(format!("Invalid protocol tweak {:?}", value))),
            }
            continue;
        }
        match tweak {
            "aa" => tweaks.set_authoritative_flag = true,
            "ad" => tweaks.set_authentic_flag = true,
            "cd" => tweaks.set_checking_disabled_flag = true,
            _ => return Err(OptionError(format!("Invalid protocol tweak {:?}", value))),
        }
    }
    if !set {
        return Err(OptionError(format!("Invalid protocol tweak {:?}", value)));
    }
    Ok(())
}

/// Work out what a bare command-line argument means.
fn interpret_argument(
    arg: &str,
    domains: &mut Vec<dns::name::Labels>,
    record_types: &mut Vec<RecordType>,
    classes: &mut Vec<Class>,
) -> Result<(), OptionError> {
    if let Some(rest) = arg.strip_prefix('@') {
        log::trace("dog::options", &format!("Got nameserver -> {:?}", rest));
        return Ok(());
    }
    match RecordType::parse(arg) {
        Ok(Some(t)) => {
            if matches!(t, RecordType::Other(OtherType::HeardOf(name, _)) if name == "OPT") {
                return Err(OptionError(
                    "OPT request is sent by default (see -Z flag)".to_string(),
                ));
            }
            log::trace("dog::options", &format!("Got qtype -> {:?}", arg));
            record_types.push(t);
            return Ok(());
        }
        Ok(None) => {}
        Err(()) => {
            return Err(OptionError(
                "OPT request is sent by default (see -Z flag)".to_string(),
            ))
        }
    }
    let class = match arg.to_ascii_lowercase().as_str() {
        "in" => Some(Class::Internet),
        "ch" => Some(Class::Chaos),
        "hs" => Some(Class::Hesiod),
        _ => None,
    };
    if let Some(class) = class {
        log::trace("dog::options", &format!("Got qclass -> {:?}", arg));
        classes.push(class);
        return Ok(());
    }
    match dns::name::Labels::parse(arg) {
        Ok(labels) => {
            let single_word = !arg.is_empty()
                && arg.is_ascii()
                && arg.chars().next().map(|c| c.is_ascii_alphabetic()).unwrap_or(false)
                && arg.chars().all(|c| c.is_ascii_alphanumeric());
            if single_word {
                log::trace(
                    "dog::options",
                    &format!("Got single-word domain -> {:?}", arg),
                );
            } else {
                log::trace("dog::options", &format!("Got domain -> {:?}", arg));
            }
            domains.push(labels);
            Ok(())
        }
        Err(()) => Err(OptionError(format!("Invalid domain {:?}", arg))),
    }
}

/// Print dog's help or version information to standard output.
pub fn print_meta(kind: &Parsed, colour: bool) {
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    let text = match (kind, colour) {
        (Parsed::Help, false) => crate::text::HELP_PLAIN,
        (Parsed::Help, true) => crate::text::HELP_COLOUR,
        (Parsed::Version, false) => crate::text::VERSION_PLAIN,
        (Parsed::Version, true) => crate::text::VERSION_COLOUR,
        (Parsed::NoDomains, false) => crate::text::HELP_PLAIN,
        (Parsed::NoDomains, true) => crate::text::HELP_COLOUR,
        _ => "",
    };
    let _ = out.write_all(text.as_bytes());
    let _ = out.flush();
}
