cat > dog/src/output.rs <<'EOF'
//! dog's output: tables, JSON, and short mode.

use dns::records::{json_escape, RecordData};
use dns::wire::{Message, Record, Section};

/// Whether dog should paint its output with colours.
pub fn colourise(setting: crate::options::ColourSetting) -> bool {
    use crate::options::ColourSetting;
    match setting {
        ColourSetting::Always => true,
        ColourSetting::Never => false,
        ColourSetting::Automatic => std::io::IsTerminal::is_terminal(&std::io::stdout()),
    }
}

fn paint(colour: bool, code: &str, text: &str) -> String {
    if colour {
        format!("\x1b[{}m{}\x1b[0m", code, text)
    } else {
        text.to_string()
    }
}

/// A single row of dog's table.
struct Row {
    type_text: String,
    type_colour: &'static str,
    name: String,
    ttl_text: String,
    marker: String,
    marker_colour: &'static str,
    data: String,
}

fn record_row(record: &Record, show_opt: bool, format_durations: bool) -> Option<Row> {
    if record.is_opt() && !show_opt {
        return None;
    }
    Some(Row {
        type_text: record.type_name(),
        type_colour: record.data.colour(),
        name: record.name.clone(),
        ttl_text: record.ttl_text(format_durations),
        marker: record.section.marker().to_string(),
        marker_colour: record.section.marker_colour(),
        data: record.data.text(),
    })
}

/// dog's text output.
pub fn text_output(responses: &[Result<Message, dns_transport::Error>], colour: bool, format_durations: bool, show_opt: bool) {
    let mut rows: Vec<Vec<Row>> = Vec::new();
    let mut statuses: Vec<Option<String>> = Vec::new();
    for response in responses {
        match response {
            Ok(message) => {
                let status = message.flags.status_name();
                statuses.push(if status.is_empty() { None } else { Some(status) });
                let mut these = Vec::new();
                for record in message.answers.iter().chain(message.authorities.iter()).chain(message.additionals.iter()) {
                    if let Some(row) = record_row(record, show_opt, format_durations) {
                        these.push(row);
                    }
                }
                rows.push(these);
            }
            Err(_) => {
                statuses.push(None);
                rows.push(Vec::new());
            }
        }
    }
    let mut type_width = 0usize;
    let mut name_width = 0usize;
    let mut ttl_width = 0usize;
    for group in &rows {
        for row in group {
            type_width = type_width.max(row.type_text.chars().count());
            name_width = name_width.max(row.name.chars().count());
            ttl_width = ttl_width.max(row.ttl_text.chars().count());
        }
    }
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    for (index, group) in rows.iter().enumerate() {
        if let Some(status) = &statuses[index] {
            let _ = std::io::Write::write_all(&mut out, format!("Status: {}\n", status).as_bytes());
        }
        for row in group {
            let line = format!(
                "{} {} {} {} {}",
                pad_right(&paint(colour, row.type_colour, &row.type_text), type_width, colour, row.type_colour),
                pad_left(&paint(colour, "1;34", &row.name), name_width),
                row.ttl_text,
                paint(colour, row.marker_colour, &row.marker),
                row.data,
            );
            let _ = std::io::Write::write_all(&mut out, format!("{}\n", line).as_bytes());
        }
    }
}

fn pad_left(text: &str, width: usize) -> String {
    let len = text.chars().count();
    if len >= width {
        text.to_string()
    } else {
        format!("{}{}", " ".repeat(width - len), text)
    }
}

/// Pad a possibly-coloured string on the right, counting only its visible width.
fn pad_right(text: &str, width: usize, colour: bool, code: &str) -> String {
    let visible = if colour {
        strip_codes(text).chars().count()
    } else {
        text.chars().count()
    };
    if visible >= width {
        text.to_string()
    } else {
        format!("{}{}", text, " ".repeat(width - visible))
    }
}

fn strip_codes(text: &str) -> String {
    let mut out = String::new();
    let mut chars = text.chars();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            for c in chars.by_ref() {
                if c == 'm' {
                    break;
                }
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// dog's JSON output.
pub fn json_output(responses: &[Result<Message, dns_transport::Error>], duration: Option<(u64, u32)>) {
    let mut parts: Vec<String> = Vec::new();
    for response in responses {
        if let Ok(message) = response {
            let mut queries: Vec<String> = Vec::new();
            for query in &message.queries {
                queries.push(query.json());
            }
            parts.push(format!(
                "{{\"queries\":[{}],\"answers\":[{}],\"authorities\":[{}],\"additionals\":[{}]}}",
                queries.join(","),
                json_records(&message.answers),
                json_records(&message.authorities),
                json_records(&message.additionals),
            ));
        }
    }
    let mut out = format!("{{\"responses\":[{}]}}", parts.join(","));
    if let Some((secs, millis)) = duration {
        out.push_str(&format!(
            ",\"duration\":{{\"secs\":{},\"millis\":{}}}",
            secs, millis
        ));
        out = format!("{{\"responses\":[{}],\"duration\":{{\"secs\":{},\"millis\":{}}}}}", parts.join(","), secs, millis);
    }
    println!("{}", out);
}

fn json_records(records: &[Record]) -> String {
    let parts: Vec<String> = records.iter().map(|r| r.json()).collect();
    parts.join(",")
}

/// dog's short mode: nothing but the data.
pub fn short_output(responses: &[Result<Message, dns_transport::Error>]) -> usize {
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    let mut count = 0usize;
    for response in responses {
        if let Ok(message) = response {
            for record in &message.answers {
                let _ = std::io::Write::write_all(
                    &mut out,
                    format!("{}\n", record.data.text()).as_bytes(),
                );
                count += 1;
            }
        }
    }
    count
}

/// dog's status text for a response, used when dog has to say something went wrong.
pub fn status_of(message: &Message) -> String {
    message.flags.status_name()
}

pub fn data_text(record: &Record) -> String {
    record.data.text()
}

pub fn record_type(record: &Record) -> String {
    record.type_name()
}

pub fn record_json(record: &Record) -> String {
    record.json()
}

pub fn json_escape_pub(s: &str) -> String {
    json_escape(s)
}

pub fn unknown_bytes(bytes: &[u8]) -> String {
    let list: Vec<String> = bytes.iter().map(|b| b.to_string()).collect();
    format!("[{}]", list.join(", "))
}

pub fn record_data_kind(record: &Record) -> String {
    match &record.data {
        RecordData::Unknown(_) => "unknown".to_string(),
        _ => "known".to_string(),
    }
}

pub fn record_section(record: &Record) -> Section {
    record.section
}
EOF
