//! Reading the system's resolver configuration.

use std::net::IpAddr;

pub struct ResolverConfig {
    pub nameservers: Vec<IpAddr>,
}

pub enum ResolverError {
    Read(std::io::Error),
    NoNameServers,
}

impl std::fmt::Display for ResolverError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            ResolverError::Read(e) => write!(f, "{}", e),
            ResolverError::NoNameServers => write!(f, "no nameservers found"),
        }
    }
}

/// Read /etc/resolv.conf for the system's nameservers.
pub fn read() -> Result<ResolverConfig, ResolverError> {
    let contents = std::fs::read_to_string("/etc/resolv.conf").map_err(ResolverError::Read)?;
    let mut nameservers = Vec::new();
    for line in contents.lines() {
        let line = line.split('#').next().unwrap_or("");
        let mut parts = line.split_whitespace();
        if parts.next() == Some("nameserver") {
            if let Some(addr) = parts.next() {
                if let Ok(ip) = addr.parse::<IpAddr>() {
                    nameservers.push(ip);
                }
            }
        }
    }
    if nameservers.is_empty() {
        return Err(ResolverError::NoNameServers);
    }
    Ok(ResolverConfig { nameservers })
}
