//! dog: a command-line DNS client.

mod hints;
mod options;
mod output;
mod sysconf;
mod text;

use dns::log;
use dns::records::RecordType;
use dns::wire::Message;
use dns::Class;
use dns_transport::TransportType;
use options::{Edns, Format, Options, Parsed, ResolverType, TxidGenerator};
use std::io::Write;

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    log::setup();
    let parsed = match options::parse(&args) {
        Ok(parsed) => parsed,
        Err(e) => {
            eprintln!("dog: Invalid options: {}", e.0);
            std::process::exit(3);
        }
    };
    match parsed {
        Parsed::Help(colour) => {
            output_text(text::HELP_PLAIN, text::HELP_COLOUR, options::colour_on(colour));
            std::process::exit(0);
        }
        Parsed::Version(colour) => {
            output_text(
                text::VERSION_PLAIN,
                text::VERSION_COLOUR,
                options::colour_on(colour),
            );
            std::process::exit(0);
        }
        Parsed::NoDomains(colour) => {
            output_text(text::HELP_PLAIN, text::HELP_COLOUR, options::colour_on(colour));
            std::process::exit(3);
        }
        Parsed::Run(options) => run(*options),
    }
}

fn output_text(plain: &str, painted: &str, colour: bool) {
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    let _ = out.write_all(if colour { painted } else { plain }.as_bytes());
}

/// A single DNS request dog has to make.
struct Request {
    domain: dns::name::Labels,
    r#type: RecordType,
    class: Class,
    resolver: ResolverType,
    transport: TransportType,
}

fn run(options: Options) {
    let hints = hints::Hints::load();
    log::info(
        "dog",
        &format!("Running with options -> {}", options.debug_string()),
    );
    let transport = options
        .inputs
        .transport_types
        .first()
        .cloned()
        .unwrap_or(TransportType::Automatic);
    let mut requests = Vec::new();
    for domain in &options.inputs.domains {
        for r#type in &options.inputs.record_types {
            for class in &options.inputs.classes {
                for resolver in &options.inputs.resolver_types {
                    if hints.contains(&domain.to_string()) {
                        eprintln!(
                            "warning: domain {:?} also exists in hosts file",
                            domain.to_string()
                        );
                    }
                    requests.push(Request {
                        domain: domain.clone(),
                        r#type: r#type.clone(),
                        class: *class,
                        resolver: resolver.clone(),
                        transport,
                    });
                }
            }
        }
    }
    let mut responses: Vec<Result<Message, dns_transport::Error>> = Vec::new();
    let mut error = false;
    let start = std::time::Instant::now();
    let mut txid_sequence = match options.txid_generator {
        TxidGenerator::Random => None,
        TxidGenerator::Sequence(n) => Some(n),
    };
    for request in &requests {
        let txid = match &mut txid_sequence {
            Some(n) => {
                let this = *n;
                *n = n.wrapping_add(1);
                this
            }
            None => random_txid(),
        };
        match perform(request, txid, &options) {
            Ok(message) => responses.push(Ok(message)),
            Err(e) => {
                error = true;
                let _ = std::io::stderr().write_all(
                    format!("Error [{}]: {}\n", e.phase(), e.message()).as_bytes(),
                );
                responses.push(Err(e));
            }
        }
    }
    let elapsed = start.elapsed();
    match options.format.mode {
        options::OutputMode::JSON => {
            let duration = if options.measure_time {
                Some((elapsed.as_secs(), elapsed.subsec_millis()))
            } else {
                None
            };
            output::json_output(&responses, duration);
        }
        options::OutputMode::Short => {
            let count = output::short_output(&responses);
            if count == 0 {
                eprintln!("No results");
                std::process::exit(2);
            }
        }
        options::OutputMode::Text => {
            let colour = options
                .format
                .colour
                .map(output::colourise)
                .unwrap_or_else(|| output::colourise(options::ColourSetting::Automatic));
            output::text_output(
                &responses,
                colour,
                options.format.format_durations,
                matches!(options.edns, Edns::SendAndShow),
            );
        }
    }
    if options.measure_time && !matches!(options.format.mode, options::OutputMode::JSON) {
        println!("Ran in {}ms", elapsed.as_millis());
    }
    if error {
        std::process::exit(1);
    }
}

fn perform(
    request: &Request,
    txid: u16,
    options: &Options,
) -> Result<Message, dns_transport::Error> {
    let edns = !matches!(options.edns, Edns::Disable);
    let udp_payload_size = options.protocol_tweaks.udp_payload_size.unwrap_or(512);
    let packet = Message::build_query(
        txid,
        &request.domain,
        &request.r#type,
        &request.class,
        edns,
        udp_payload_size,
        options.protocol_tweaks.set_authoritative_flag,
        options.protocol_tweaks.set_authentic_flag,
        options.protocol_tweaks.set_checking_disabled_flag,
    );
    match request.transport {
        TransportType::UDP | TransportType::Automatic => {
            let addr = udp_address(&request.resolver)?;
            let mut transport = dns_transport::udp::UdpTransport::new(addr)?;
            transport.send(&packet)?;
            let mut buffer = vec![0u8; 65536];
            let n = transport.receive(&mut buffer)?;
            Message::parse(&buffer[..n]).map_err(wire_error)
        }
        TransportType::TCP => {
            let addr = udp_address(&request.resolver)?;
            let mut transport = dns_transport::tcp::TcpTransport::new(addr)?;
            transport.send(&packet, &addr)?;
            let bytes = transport.receive()?;
            Message::parse(&bytes).map_err(wire_error)
        }
        TransportType::TLS => {
            let ns = nameserver_string(&request.resolver)?;
            let mut transport = dns_transport::tls::TlsTransport::new(&ns)?;
            transport.send(&packet)?;
            let bytes = transport.receive()?;
            Message::parse(&bytes).map_err(wire_error)
        }
        TransportType::HTTPS => {
            let ns = match &request.resolver {
                ResolverType::Specific(s) => s.clone(),
                ResolverType::SystemDefault => String::new(),
            };
            let mut transport = dns_transport::https::HttpTransport::new(&ns)?;
            transport.send(&packet)?;
            let bytes = transport.receive()?;
            Message::parse(&bytes).map_err(wire_error)
        }
    }
}

fn wire_error(e: dns::name::WireError) -> dns_transport::Error {
    dns_transport::Error::Protocol(format!("Malformed packet: {}", e))
}

/// The address to send UDP and TCP packets to.
fn udp_address(
    resolver: &ResolverType,
) -> Result<std::net::SocketAddr, dns_transport::Error> {
    match resolver {
        ResolverType::Specific(addr) => dns_transport::udp::resolve(addr),
        ResolverType::SystemDefault => match sysconf::read() {
            Ok(config) => Ok(std::net::SocketAddr::new(config.nameservers[0], 53)),
            Err(e) => {
                eprintln!("dog: Could not read /etc/resolv.conf: {}", e);
                std::process::exit(4);
            }
        },
    }
}

/// The nameserver string dog hands to the TLS transport.
fn nameserver_string(resolver: &ResolverType) -> Result<String, dns_transport::Error> {
    match resolver {
        ResolverType::Specific(addr) => Ok(addr.clone()),
        ResolverType::SystemDefault => match sysconf::read() {
            Ok(config) => Ok(config.nameservers[0].to_string()),
            Err(e) => {
                eprintln!("dog: Could not read /etc/resolv.conf: {}", e);
                std::process::exit(4);
            }
        },
    }
}

fn random_txid() -> u16 {
    use std::hash::{Hash, Hasher};
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0)
        .hash(&mut hasher);
    let value = hasher.finish() as u16;
    if value == 0 {
        0x1234
    } else {
        value
    }
}
